(function(){"use strict";if(document.readyState!=="loading"){throw new Error("Blogger embed must load synchronously during HTML parsing");}document.write("<div id=\"lectureHallPage\">\n\n<style>\n/* =========================================================\n   GI\u1ea2NG \u0110\u01af\u1edcNG OCD\n   LECTURE HALL v1.6.1\n   TRANSITIONAL IDENTITY\n\n   GI\u1eee NGUY\u00caN:\n   - Ph\u00f2ng h\u1ecdc Ho\u00e0 B\u00ecnh\n   - Ph\u00f2ng h\u1ecdc H\u1ea1nh Ph\u00fac\n   - Ph\u00f2ng Thi T\u1ed1t Nghi\u1ec7p\n   - Ho\u1ea1t \u0111\u1ed9ng g\u1ea7n \u0111\u00e2y\n   - M\u00e3 \u01b0u ti\u00ean Goiungho800k / MaHocVien\n\n   \u0110\u1ecaNH DANH:\n   1. M\u00e3 \u01b0u ti\u00ean -> \u0111\u01b0\u1ee3c v\u00e0o c\u1ea3 hai ph\u00f2ng\n   2. HocVien -> ngu\u1ed3n \u0111\u1ecbnh danh ch\u00ednh\n   3. N\u1ebfu ch\u01b0a c\u00f3 trong HocVien -> fallback XepHang\n   4. N\u1ebfu \u0111\u00e3 c\u00f3 HocVien th\u00ec tr\u1ea1ng th\u00e1i HocVien c\u00f3 quy\u1ec1n cao nh\u1ea5t\n\n   PH\u00c2N PH\u00d2NG:\n   - Ho\u00e0 B\u00ecnh: 01 / 02 / 03\n   - H\u1ea1nh Ph\u00fac: 01 / 02 / 03 / 04\n\n   L\u1ecaCH:\n   - Ho\u00e0 B\u00ecnh: Th\u1ee9 S\u00e1u 19:00\u201321:00\n   - H\u1ea1nh Ph\u00fac: Th\u1ee9 B\u1ea3y 19:00\u201321:00\n========================================================= */\n\n\n/* =========================================================\n   ROOT\n========================================================= */\n\n#lectureHallPage{\n    --gd-paper:#ffffff;\n    --gd-ink:#302a26;\n    --gd-muted:#786f66;\n    --gd-line:#e7ded3;\n\n    --gd-brown:#765344;\n    --gd-brown-dark:#51372d;\n\n    --gd-red:#963333;\n\n    --gd-gold:#b58440;\n    --gd-gold-soft:#f6ebd7;\n\n    --gd-green:#247159;\n    --gd-green-soft:#e8f5ef;\n\n    --gd-blue:#315f91;\n    --gd-blue-soft:#edf4fb;\n\n    --gd-purple:#745394;\n    --gd-purple-soft:#f4eff8;\n\n    --gd-shadow:\n        0 12px 34px rgba(68,48,36,.08);\n\n    --gd-shadow-small:\n        0 5px 18px rgba(68,48,36,.07);\n\n    width:100%;\n    max-width:1180px;\n    margin:0 auto;\n    padding:22px 12px 50px;\n\n    box-sizing:border-box;\n\n    font-family:\n        Arial,\n        \"Helvetica Neue\",\n        sans-serif;\n\n    color:var(--gd-ink);\n}\n\n\n#lectureHallPage *,\n#lectureHallPage *::before,\n#lectureHallPage *::after{\n    box-sizing:border-box;\n}\n\n\n/* =========================================================\n   HEADER\n========================================================= */\n\n.gd-header{\n    position:relative;\n    overflow:hidden;\n\n    margin-bottom:24px;\n    padding:36px 24px 32px;\n\n    border:1px solid #eadfce;\n    border-radius:24px;\n\n    background:\n        radial-gradient(\n            circle at 10% 0%,\n            rgba(184,135,66,.13),\n            transparent 30%\n        ),\n        radial-gradient(\n            circle at 95% 100%,\n            rgba(159,49,49,.08),\n            transparent 34%\n        ),\n        linear-gradient(\n            145deg,\n            #fffdf8,\n            #f8f2e8\n        );\n\n    box-shadow:var(--gd-shadow);\n\n    text-align:center;\n}\n\n\n.gd-header-seal{\n    display:inline-flex;\n    align-items:center;\n    justify-content:center;\n\n    width:54px;\n    height:54px;\n\n    margin-bottom:14px;\n\n    border-radius:16px;\n\n    background:\n        linear-gradient(\n            145deg,\n            #aa3939,\n            #7e2626\n        );\n\n    color:#ffffff;\n\n    font-family:serif;\n    font-size:25px;\n    font-weight:700;\n\n    box-shadow:\n        0 8px 18px\n        rgba(126,38,38,.19);\n\n    transform:rotate(-3deg);\n}\n\n\n.gd-main-title{\n    margin:0;\n\n    color:var(--gd-brown-dark);\n\n    font-family:\n        Georgia,\n        \"Times New Roman\",\n        serif;\n\n    font-size:34px;\n    line-height:1.15;\n    font-weight:900;\n    letter-spacing:1.5px;\n}\n\n\n.gd-main-subtitle{\n    max-width:700px;\n\n    margin:11px auto 0;\n\n    color:var(--gd-muted);\n\n    font-size:14px;\n    line-height:1.75;\n}\n\n\n.gd-header-status{\n    display:inline-flex;\n    align-items:center;\n    gap:7px;\n\n    margin-top:17px;\n    padding:7px 12px;\n\n    border:1px solid #e5ded3;\n    border-radius:999px;\n\n    background:rgba(255,255,255,.78);\n\n    color:var(--gd-muted);\n\n    font-size:11px;\n    font-weight:800;\n}\n\n\n.gd-header-status.live{\n    border-color:#d4e9dc;\n    background:var(--gd-green-soft);\n    color:var(--gd-green);\n}\n\n\n.gd-status-dot{\n    display:inline-block;\n\n    width:8px;\n    height:8px;\n\n    border-radius:50%;\n\n    background:#aaa39b;\n}\n\n\n.gd-header-status.live .gd-status-dot{\n    background:#2c986d;\n\n    box-shadow:\n        0 0 0 4px\n        rgba(44,152,109,.12);\n\n    animation:\n        gdPulse 1.6s ease-in-out infinite;\n}\n\n\n@keyframes gdPulse{\n\n    0%,\n    100%{\n        opacity:1;\n    }\n\n    50%{\n        opacity:.45;\n    }\n\n}\n\n\n/* =========================================================\n   SECTION\n========================================================= */\n\n.gd-section{\n    margin-top:22px;\n}\n\n\n.gd-section-heading{\n    margin-bottom:13px;\n}\n\n\n.gd-section-kicker{\n    margin-bottom:5px;\n\n    color:var(--gd-red);\n\n    font-size:10px;\n    font-weight:900;\n    letter-spacing:1.5px;\n}\n\n\n.gd-section-title{\n    margin:0;\n\n    color:var(--gd-brown-dark);\n\n    font-family:\n        Georgia,\n        \"Times New Roman\",\n        serif;\n\n    font-size:23px;\n    font-weight:900;\n}\n\n\n.gd-section-desc{\n    margin:5px 0 0;\n\n    color:var(--gd-muted);\n\n    font-size:12px;\n    line-height:1.55;\n}\n\n\n/* =========================================================\n   ROOMS\n========================================================= */\n\n.gd-room-grid{\n    display:grid;\n\n    grid-template-columns:\n        repeat(2,minmax(0,1fr));\n\n    gap:16px;\n}\n\n\n.gd-room{\n    position:relative;\n    overflow:hidden;\n\n    border:1px solid var(--gd-line);\n    border-radius:21px;\n\n    background:\n        linear-gradient(\n            145deg,\n            #ffffff,\n            #fcfaf5\n        );\n\n    box-shadow:var(--gd-shadow-small);\n}\n\n\n.gd-room.live{\n    border-color:\n        rgba(36,113,89,.35);\n\n    box-shadow:\n        0 8px 26px\n        rgba(36,113,89,.10);\n}\n\n\n/* =========================================================\n   ROOM BANNER\n========================================================= */\n\n.gd-room-banner{\n    position:relative;\n\n    width:100%;\n\n    aspect-ratio:16 / 8.2;\n\n    overflow:hidden;\n\n    background:#eee8df;\n}\n\n\n.gd-room-banner img{\n    display:block;\n\n    width:100%;\n    height:100%;\n\n    object-fit:cover;\n    object-position:center;\n\n    transition:\n        transform .35s ease;\n}\n\n\n.gd-room:hover .gd-room-banner img{\n    transform:scale(1.025);\n}\n\n\n.gd-room-banner::after{\n    content:\"\";\n\n    position:absolute;\n\n    left:0;\n    right:0;\n    bottom:0;\n\n    height:40%;\n\n    background:\n        linear-gradient(\n            to bottom,\n            transparent,\n            rgba(38,27,22,.16)\n        );\n\n    pointer-events:none;\n}\n\n\n.gd-room-body{\n    padding:17px 19px 19px;\n}\n\n\n/* =========================================================\n   ROOM TOP\n========================================================= */\n\n.gd-room-top{\n    display:flex;\n\n    align-items:flex-start;\n    justify-content:space-between;\n\n    gap:12px;\n}\n\n\n.gd-room-identity{\n    display:flex;\n    align-items:center;\n    gap:12px;\n\n    min-width:0;\n}\n\n\n.gd-room-icon{\n    display:flex;\n    align-items:center;\n    justify-content:center;\n\n    width:48px;\n    height:48px;\n\n    flex:0 0 auto;\n\n    border-radius:15px;\n\n    background:\n        linear-gradient(\n            145deg,\n            #f8ecda,\n            #efe0c5\n        );\n\n    font-size:23px;\n}\n\n\n.gd-room-label{\n    margin-bottom:3px;\n\n    color:var(--gd-gold);\n\n    font-size:10px;\n    font-weight:900;\n    letter-spacing:1px;\n}\n\n\n.gd-room-name{\n    margin:0;\n\n    color:var(--gd-brown-dark);\n\n    font-family:\n        Georgia,\n        \"Times New Roman\",\n        serif;\n\n    font-size:20px;\n    line-height:1.25;\n    font-weight:900;\n}\n\n\n/* =========================================================\n   STATUS\n========================================================= */\n\n.gd-room-status{\n    display:inline-flex;\n    align-items:center;\n    gap:6px;\n\n    padding:6px 9px;\n\n    border:1px solid #e3ddd4;\n    border-radius:999px;\n\n    background:#f6f4f0;\n\n    color:#7e766e;\n\n    font-size:9px;\n    font-weight:900;\n\n    white-space:nowrap;\n}\n\n\n.gd-room-status.live{\n    border-color:#d3eadc;\n    background:var(--gd-green-soft);\n    color:var(--gd-green);\n}\n\n\n.gd-room-status-dot{\n    width:6px;\n    height:6px;\n\n    border-radius:50%;\n\n    background:#aaa39b;\n}\n\n\n.gd-room-status.live .gd-room-status-dot{\n    background:#2d966c;\n\n    animation:\n        gdPulse 1.6s ease-in-out infinite;\n}\n\n\n.gd-room-schedule{\n    margin-top:7px;\n\n    color:#948b82;\n\n    font-size:9px;\n    font-weight:700;\n\n    text-align:right;\n}\n\n\n/* =========================================================\n   NOTE\n========================================================= */\n\n.gd-room-note{\n    margin:14px 0 15px;\n\n    padding:10px 12px;\n\n    border-radius:11px;\n\n    background:#f8f5ef;\n\n    color:#776e64;\n\n    font-size:11px;\n    line-height:1.55;\n}\n\n\n/* =========================================================\n   VERIFY\n========================================================= */\n\n.gd-verify-label{\n    display:block;\n\n    margin-bottom:7px;\n\n    color:#5d554d;\n\n    font-size:11px;\n    font-weight:800;\n}\n\n\n.gd-verify-row{\n    display:grid;\n\n    grid-template-columns:\n        minmax(0,1fr) auto;\n\n    gap:8px;\n}\n\n\n.gd-code-input{\n    width:100%;\n    min-width:0;\n\n    height:44px;\n\n    padding:0 13px;\n\n    border:1px solid #dcd5cc;\n    border-radius:12px;\n\n    outline:none;\n\n    background:#ffffff;\n\n    color:#292524;\n\n    font-size:14px;\n    font-weight:700;\n}\n\n\n.gd-code-input:focus{\n    border-color:#a98059;\n\n    box-shadow:\n        0 0 0 3px\n        rgba(169,128,89,.11);\n}\n\n\n.gd-code-input::placeholder{\n    color:#aaa39b;\n\n    font-weight:500;\n}\n\n\n.gd-verify-button{\n    min-height:44px;\n\n    padding:0 15px;\n\n    border:0;\n    border-radius:12px;\n\n    background:\n        linear-gradient(\n            135deg,\n            #785548,\n            #51382f\n        );\n\n    color:#ffffff;\n\n    font-size:11px;\n    font-weight:900;\n\n    cursor:pointer;\n\n    box-shadow:\n        0 5px 14px\n        rgba(81,56,47,.16);\n}\n\n\n.gd-verify-button:disabled{\n    opacity:.55;\n    cursor:not-allowed;\n}\n\n\n/* =========================================================\n   MESSAGE\n========================================================= */\n\n.gd-room-message{\n    display:none;\n\n    margin-top:10px;\n    padding:10px 12px;\n\n    border-radius:11px;\n\n    font-size:11px;\n    line-height:1.5;\n    font-weight:700;\n}\n\n\n.gd-room-message.show{\n    display:block;\n}\n\n\n.gd-room-message.loading{\n    background:#f6f4ef;\n    color:#776e64;\n}\n\n\n.gd-room-message.success{\n    border:1px solid #cee5d7;\n\n    background:var(--gd-green-soft);\n\n    color:#24694f;\n}\n\n\n.gd-room-message.error{\n    border:1px solid #efd4d1;\n\n    background:#fff0ee;\n\n    color:#9a3630;\n}\n\n\n.gd-room-message.warning{\n    border:1px solid #eadcb5;\n\n    background:#fff8e6;\n\n    color:#87611c;\n}\n\n\n/* =========================================================\n   MEET\n========================================================= */\n\n.gd-meet-access{\n    display:none;\n\n    margin-top:11px;\n}\n\n\n.gd-meet-access.show{\n    display:block;\n}\n\n\n.gd-meet-button{\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    gap:8px;\n\n    width:100%;\n\n    min-height:46px;\n\n    padding:10px 14px;\n\n    border-radius:13px;\n\n    background:\n        linear-gradient(\n            135deg,\n            #24765b,\n            #195944\n        );\n\n    color:#ffffff !important;\n\n    text-decoration:none !important;\n\n    font-size:12px;\n    font-weight:900;\n\n    box-shadow:\n        0 6px 18px\n        rgba(36,118,91,.18);\n}\n\n\n.gd-meet-small{\n    margin-top:7px;\n\n    color:#8b837a;\n\n    font-size:9px;\n    line-height:1.5;\n\n    text-align:center;\n}\n\n\n/* =========================================================\n   GRADUATION EXAM\n========================================================= */\n\n.gd-graduation-room{\n    position:relative;\n    overflow:hidden;\n\n    display:grid;\n\n    grid-template-columns:\n        auto minmax(0,1fr) auto;\n\n    align-items:center;\n\n    gap:16px;\n\n    margin-top:16px;\n\n    padding:17px 19px;\n\n    border:1px solid #dfc994;\n    border-radius:18px;\n\n    background:\n        radial-gradient(\n            circle at 5% 20%,\n            rgba(181,132,64,.14),\n            transparent 30%\n        ),\n        linear-gradient(\n            135deg,\n            #fff9eb,\n            #fffdf8\n        );\n\n    box-shadow:\n        var(--gd-shadow-small);\n}\n\n\n.gd-graduation-icon{\n    display:flex;\n\n    width:52px;\n    height:52px;\n\n    align-items:center;\n    justify-content:center;\n\n    border-radius:15px;\n\n    background:\n        linear-gradient(\n            145deg,\n            #efe0bd,\n            #e4c98c\n        );\n\n    font-size:24px;\n\n    flex:0 0 auto;\n}\n\n\n.gd-graduation-label{\n    color:#9b7134;\n\n    font-size:9px;\n    font-weight:900;\n    letter-spacing:1px;\n}\n\n\n.gd-graduation-title{\n    margin:2px 0 3px;\n\n    color:var(--gd-brown-dark);\n\n    font-family:\n        Georgia,\n        \"Times New Roman\",\n        serif;\n\n    font-size:19px;\n    font-weight:900;\n}\n\n\n.gd-graduation-desc{\n    margin:0;\n\n    color:var(--gd-muted);\n\n    font-size:11px;\n    line-height:1.55;\n}\n\n\n.gd-graduation-button{\n    display:inline-flex;\n\n    min-height:42px;\n\n    padding:9px 16px;\n\n    align-items:center;\n    justify-content:center;\n\n    border-radius:11px;\n\n    background:\n        linear-gradient(\n            135deg,\n            #9c7136,\n            #765125\n        );\n\n    color:#ffffff !important;\n\n    text-decoration:none !important;\n\n    font-size:10px;\n    font-weight:900;\n\n    white-space:nowrap;\n\n    box-shadow:\n        0 5px 14px\n        rgba(118,81,37,.17);\n}\n\n\n.gd-graduation-button:hover{\n    opacity:.92;\n}\n\n\n/* =========================================================\n   PRIVACY\n========================================================= */\n\n.gd-privacy-note{\n    display:flex;\n\n    align-items:flex-start;\n\n    gap:10px;\n\n    margin-top:13px;\n\n    padding:11px 13px;\n\n    border:1px solid #ebe5dc;\n    border-radius:13px;\n\n    background:\n        rgba(255,255,255,.65);\n\n    color:#81786f;\n\n    font-size:10px;\n    line-height:1.55;\n}\n\n\n/* =========================================================\n   ACTIVITY\n========================================================= */\n\n.gd-activity-card{\n    overflow:hidden;\n\n    border:1px solid var(--gd-line);\n    border-radius:21px;\n\n    background:#ffffff;\n\n    box-shadow:\n        var(--gd-shadow-small);\n}\n\n\n.gd-activity-toolbar{\n    display:flex;\n\n    align-items:center;\n    justify-content:space-between;\n\n    gap:12px;\n\n    padding:13px 15px;\n\n    border-bottom:\n        1px solid #eee7de;\n\n    background:#fcfaf6;\n}\n\n\n.gd-filter-scroll{\n    display:flex;\n\n    gap:6px;\n\n    overflow-x:auto;\n\n    scrollbar-width:none;\n}\n\n\n.gd-filter-scroll::-webkit-scrollbar{\n    display:none;\n}\n\n\n.gd-filter-button{\n    flex:0 0 auto;\n\n    padding:7px 10px;\n\n    border:1px solid #e2dad0;\n    border-radius:999px;\n\n    background:#ffffff;\n\n    color:#71685f;\n\n    font-size:9px;\n    font-weight:900;\n\n    cursor:pointer;\n}\n\n\n.gd-filter-button.active{\n    border-color:#805b4d;\n\n    background:#805b4d;\n\n    color:#ffffff;\n}\n\n\n.gd-refresh-button{\n    flex:0 0 auto;\n\n    padding:7px 10px;\n\n    border:1px solid #e0d8ce;\n    border-radius:10px;\n\n    background:#ffffff;\n\n    color:#625b54;\n\n    font-size:9px;\n    font-weight:800;\n\n    cursor:pointer;\n}\n\n\n.gd-activity-feed{\n    padding:4px 15px 6px;\n}\n\n\n.gd-activity-item{\n    display:grid;\n\n    grid-template-columns:\n        42px minmax(0,1fr) auto;\n\n    gap:11px;\n\n    padding:15px 0;\n\n    border-bottom:\n        1px solid #f0ebe4;\n}\n\n\n.gd-activity-item:last-child{\n    border-bottom:0;\n}\n\n\n.gd-activity-icon{\n    display:flex;\n\n    align-items:center;\n    justify-content:center;\n\n    width:40px;\n    height:40px;\n\n    border-radius:13px;\n\n    font-size:18px;\n}\n\n\n.gd-activity-item.submission .gd-activity-icon{\n    background:var(--gd-blue-soft);\n}\n\n\n.gd-activity-item.grade .gd-activity-icon{\n    background:var(--gd-gold-soft);\n}\n\n\n.gd-activity-item.comment .gd-activity-icon{\n    background:var(--gd-purple-soft);\n}\n\n\n.gd-activity-item.gift .gd-activity-icon{\n    background:#fff0f0;\n}\n\n\n.gd-activity-content{\n    align-self:center;\n    min-width:0;\n}\n\n\n.gd-activity-text{\n    color:#4b4540;\n\n    font-size:12px;\n    line-height:1.55;\n}\n\n\n.gd-activity-name{\n    color:var(--gd-brown-dark);\n\n    font-weight:900;\n}\n\n\n.gd-activity-meta{\n    margin-top:4px;\n\n    color:#958d84;\n\n    font-size:9px;\n    font-weight:800;\n}\n\n\n.gd-activity-time{\n    align-self:center;\n\n    padding-left:8px;\n\n    color:#978f86;\n\n    font-size:9px;\n\n    white-space:nowrap;\n\n    text-align:right;\n}\n\n\n.gd-empty{\n    padding:35px 15px;\n\n    color:#8d857d;\n\n    font-size:11px;\n    line-height:1.6;\n\n    text-align:center;\n}\n\n\n.gd-load-more-wrap{\n    display:none;\n\n    padding:0 15px 15px;\n\n    text-align:center;\n}\n\n\n.gd-load-more-wrap.show{\n    display:block;\n}\n\n\n.gd-load-more{\n    padding:9px 16px;\n\n    border:1px solid #ddd5cb;\n    border-radius:11px;\n\n    background:#faf8f4;\n\n    color:#655d55;\n\n    font-size:10px;\n    font-weight:900;\n\n    cursor:pointer;\n}\n\n\n/* =========================================================\n   MOBILE\n========================================================= */\n\n@media(max-width:760px){\n\n    #lectureHallPage{\n        padding:14px 8px 38px;\n    }\n\n    .gd-header{\n        padding:28px 16px 25px;\n        border-radius:19px;\n    }\n\n    .gd-main-title{\n        font-size:28px;\n    }\n\n    .gd-main-subtitle{\n        font-size:12px;\n    }\n\n    .gd-room-grid{\n        grid-template-columns:\n            repeat(2,minmax(0,1fr));\n\n        gap:8px;\n    }\n\n    .gd-room{\n        border-radius:16px;\n    }\n\n    .gd-room-banner{\n        aspect-ratio:1.35 / 1;\n    }\n\n    .gd-room-body{\n        padding:11px 9px 12px;\n    }\n\n    .gd-room-top{\n        display:block;\n    }\n\n    .gd-room-identity{\n        display:block;\n    }\n\n    .gd-room-icon{\n        width:38px;\n        height:38px;\n\n        margin-bottom:7px;\n\n        border-radius:11px;\n\n        font-size:18px;\n    }\n\n    .gd-room-name{\n        font-size:15px;\n    }\n\n    .gd-room-status{\n        margin-top:8px;\n\n        padding:5px 6px;\n\n        font-size:7px;\n    }\n\n    .gd-room-schedule{\n        text-align:left;\n        font-size:8px;\n    }\n\n    .gd-room-note{\n        margin:10px 0 11px;\n\n        padding:8px;\n\n        font-size:8.5px;\n    }\n\n    .gd-verify-label{\n        font-size:9px;\n    }\n\n    .gd-verify-row{\n        grid-template-columns:1fr;\n    }\n\n    .gd-code-input{\n        height:40px;\n\n        padding:0 9px;\n\n        font-size:11px;\n    }\n\n    .gd-verify-button{\n        min-height:37px;\n\n        font-size:9px;\n    }\n\n    .gd-room-message{\n        padding:8px;\n\n        font-size:8.5px;\n    }\n\n    .gd-meet-button{\n        min-height:40px;\n\n        padding:8px;\n\n        font-size:8.5px;\n    }\n\n    .gd-graduation-room{\n        grid-template-columns:\n            auto minmax(0,1fr);\n\n        gap:10px;\n\n        padding:13px;\n\n        border-radius:15px;\n    }\n\n    .gd-graduation-icon{\n        width:42px;\n        height:42px;\n\n        border-radius:12px;\n\n        font-size:19px;\n    }\n\n    .gd-graduation-title{\n        font-size:15px;\n    }\n\n    .gd-graduation-desc{\n        font-size:9px;\n    }\n\n    .gd-graduation-button{\n        grid-column:1 / -1;\n\n        width:100%;\n\n        min-height:39px;\n\n        font-size:9px;\n    }\n\n    .gd-activity-item{\n        grid-template-columns:\n            36px minmax(0,1fr);\n\n        gap:9px;\n    }\n\n    .gd-activity-icon{\n        width:34px;\n        height:34px;\n\n        font-size:15px;\n    }\n\n    .gd-activity-text{\n        font-size:10px;\n    }\n\n    .gd-activity-time{\n        grid-column:2;\n\n        padding:0;\n\n        text-align:left;\n\n        font-size:8px;\n    }\n\n}\n\n/* =========================================================\n   v1.9.0 \u2013 TH\u01af VI\u1ec6N L\u00c2M M\u00d4 (b\u1ea3n l\u00e2m l\u1edbn + th\u1ea3 tim)\n========================================================= */\n\n.gd-lammo-intro{\n    color:#6f665d;\n    font-size:12px;\n    line-height:1.5;\n    font-weight:700;\n}\n\n.gd-lammo-actions{\n    display:flex;\n    align-items:center;\n    gap:8px;\n    flex:0 0 auto;\n}\n\n#lectureHallPage .gd-lammo-cta{\n    display:inline-flex;\n    align-items:center;\n    justify-content:center;\n    min-height:38px;\n    padding:8px 16px;\n    border-radius:11px;\n    background:linear-gradient(135deg,#a33a3a,#7b2626) !important;\n    color:#ffffff !important;\n    text-decoration:none !important;\n    font-size:12px;\n    font-weight:900;\n    white-space:nowrap;\n    box-shadow:0 5px 14px rgba(123,38,38,.18);\n}\n\n#lectureHallPage .gd-lammo-cta:hover{\n    opacity:.92;\n}\n\n#lectureHallPage .gd-lammo-grid{\n    display:grid;\n    grid-template-columns:repeat(4,minmax(0,1fr));\n    gap:14px;\n    padding:15px;\n}\n\n#lectureHallPage .gd-lammo-grid > .gd-empty{\n    grid-column:1 / -1;\n}\n\n.gd-lammo-card{\n    position:relative;\n    display:flex;\n    flex-direction:column;\n    min-width:0;\n    overflow:hidden;\n    border:1px solid #e6dccd;\n    border-radius:16px;\n    background:#fffdf8;\n    box-shadow:0 4px 14px rgba(68,48,36,.06);\n}\n\n#lectureHallPage .gd-lammo-photo{\n    display:block;\n    width:100%;\n    aspect-ratio:3 / 4;\n    margin:0;\n    padding:8px;\n    border:0;\n    border-radius:0;\n    background:#eee6d9;\n    cursor:zoom-in;\n}\n\n.gd-lammo-photo img{\n    display:block;\n    width:100%;\n    height:100%;\n    object-fit:contain;\n}\n\n.gd-lammo-photo.is-error{\n    background:#eee6d9 linear-gradient(135deg,transparent 48%,#e0d4c2 49%,#e0d4c2 51%,transparent 52%);\n}\n\n#lectureHallPage .gd-lammo-heart{\n    position:absolute;\n    top:10px;\n    right:10px;\n    z-index:2;\n    display:inline-flex;\n    align-items:center;\n    gap:5px;\n    min-height:34px;\n    padding:6px 11px;\n    border:1px solid #e8cfc5;\n    border-radius:999px;\n    background:rgba(255,253,248,.94);\n    color:#a04538;\n    font:800 13px/1 Arial,sans-serif;\n    cursor:pointer;\n    box-shadow:0 3px 10px rgba(68,48,36,.12);\n}\n\n#lectureHallPage .gd-lammo-heart span{\n    font-size:16px;\n    line-height:1;\n}\n\n#lectureHallPage .gd-lammo-heart:hover{\n    background:#fbe6dd;\n}\n\n#lectureHallPage .gd-lammo-heart.is-liked{\n    border-color:#e7b5b5;\n    background:#fff0f0;\n    color:#c33235;\n}\n\n#lectureHallPage .gd-lammo-heart:disabled{\n    opacity:.7;\n    cursor:wait;\n}\n\n.gd-lammo-info{\n    padding:11px 12px 13px;\n    min-width:0;\n}\n\n.gd-lammo-name{\n    color:var(--gd-brown-dark);\n    font-size:13px;\n    font-weight:900;\n    line-height:1.35;\n    white-space:nowrap;\n    overflow:hidden;\n    text-overflow:ellipsis;\n}\n\n.gd-lammo-sub{\n    margin-top:3px;\n    color:#8a8178;\n    font-size:11px;\n    font-weight:700;\n}\n\n.gd-lammo-title{\n    margin-top:7px;\n    color:#7b2626;\n    font-family:Georgia,\"Times New Roman\",serif;\n    font-size:14px;\n    font-weight:900;\n    line-height:1.35;\n    overflow:hidden;\n    display:-webkit-box;\n    -webkit-line-clamp:2;\n    -webkit-box-orient:vertical;\n}\n\n#lectureHallPage a.gd-lammo-title{\n    color:#7b2626 !important;\n    text-decoration:none !important;\n    cursor:pointer;\n}\n\n#lectureHallPage a.gd-lammo-title:hover{\n    text-decoration:underline !important;\n}\n\n.gd-lammo-time{\n    margin-top:6px;\n    color:#9a9188;\n    font-size:10px;\n    font-weight:700;\n}\n\n.gd-lammo-status{\n    display:none;\n    margin:0 15px 12px;\n    padding:9px 12px;\n    border:1px solid #efd4d1;\n    border-radius:11px;\n    background:#fff0ee;\n    color:#9a3630;\n    font-size:12px;\n    font-weight:700;\n}\n\n.gd-lammo-status.show{\n    display:block;\n}\n\n.gd-lammo-viewer{\n    position:fixed;\n    inset:0;\n    z-index:2147483000;\n    display:none;\n    align-items:center;\n    justify-content:center;\n    padding:16px;\n    background:rgba(20,14,10,.86);\n}\n\n.gd-lammo-viewer.show{\n    display:flex;\n}\n\n.gd-lammo-viewer figure{\n    position:relative;\n    max-width:min(960px,100%);\n    max-height:100%;\n    margin:0;\n    text-align:center;\n}\n\n.gd-lammo-viewer img{\n    display:block;\n    max-width:100%;\n    max-height:calc(100vh - 110px);\n    max-height:calc(100dvh - 110px);\n    margin:0 auto;\n    border-radius:10px;\n    background:#faf7ef;\n    object-fit:contain;\n}\n\n.gd-lammo-viewer figcaption{\n    margin-top:10px;\n    color:#f6eee2;\n    font-size:13px;\n    font-weight:700;\n    line-height:1.5;\n}\n\n#lectureHallPage .gd-lammo-close{\n    position:fixed;\n    top:12px;\n    right:12px;\n    width:42px;\n    height:42px;\n    border:0;\n    border-radius:50%;\n    background:rgba(255,255,255,.92);\n    color:#3b2a22;\n    font:900 22px/1 Arial,sans-serif;\n    cursor:pointer;\n}\n\n@media(max-width:1000px){\n\n    #lectureHallPage .gd-lammo-grid{\n        grid-template-columns:repeat(3,minmax(0,1fr));\n    }\n\n}\n\n@media(max-width:760px){\n\n    .gd-lammo-toolbar{\n        flex-direction:column;\n        align-items:stretch;\n    }\n\n    .gd-lammo-actions .gd-lammo-cta{\n        flex:1 1 auto;\n    }\n\n    #lectureHallPage .gd-lammo-grid{\n        grid-template-columns:repeat(2,minmax(0,1fr));\n        gap:10px;\n        padding:10px;\n    }\n\n    .gd-lammo-card{\n        border-radius:13px;\n    }\n\n    #lectureHallPage .gd-lammo-photo{\n        padding:5px;\n    }\n\n    #lectureHallPage .gd-lammo-heart{\n        top:7px;\n        right:7px;\n        min-height:32px;\n        padding:5px 9px;\n        font-size:12px;\n    }\n\n    .gd-lammo-info{\n        padding:9px 9px 11px;\n    }\n\n    .gd-lammo-name{\n        font-size:12px;\n    }\n\n    .gd-lammo-sub{\n        font-size:10px;\n    }\n\n    .gd-lammo-title{\n        font-size:13px;\n    }\n\n}\n\n</style>\n\n\n<div id=\"lectureHallApp\">\n\n\n<!-- =========================================================\n     HEADER\n========================================================= -->\n\n<header class=\"gd-header\">\n\n    <div class=\"gd-header-seal\">\n        \u5b78\n    </div>\n\n    <h1 class=\"gd-main-title\">\n        GI\u1ea2NG \u0110\u01af\u1edcNG\n    </h1>\n\n    <p class=\"gd-main-subtitle\">\n        Kh\u00f4ng gian h\u1ecdc t\u1eadp tr\u1ef1c tuy\u1ebfn d\u00e0nh cho h\u1ecdc vi\u00ean.\n        H\u1ec7 th\u1ed1ng t\u1ef1 nh\u1eadn di\u1ec7n h\u1ecdc vi\u00ean qua Minh H\u1ed3ng v\u00e0 m\u1edf \u0111\u00fang ph\u00f2ng h\u1ecdc c\u1ee7a b\u1ea1n.\n    </p>\n\n    <div\n        id=\"gdHeaderStatus\"\n        class=\"gd-header-status\"\n    >\n        <span class=\"gd-status-dot\"></span>\n\n        <span id=\"gdHeaderStatusText\">\n            \u0110ang ki\u1ec3m tra l\u1ecbch h\u1ecdc...\n        </span>\n    </div>\n\n</header>\n\n\n\n<!-- =========================================================\n     ROOMS\n========================================================= -->\n\n<section class=\"gd-section\">\n\n    <div class=\"gd-section-heading\">\n\n        <div class=\"gd-section-kicker\">\n            PH\u00d2NG H\u1eccC TR\u1ef0C TUY\u1ebeN\n        </div>\n\n        <h2 class=\"gd-section-title\">\n            Ph\u00f2ng h\u1ecdc\n        </h2>\n\n        <p class=\"gd-section-desc\">\n            Ph\u00f2ng Ho\u00e0 B\u00ecnh h\u1ecdc t\u1ed1i Th\u1ee9 S\u00e1u.\n            Ph\u00f2ng H\u1ea1nh Ph\u00fac h\u1ecdc t\u1ed1i Th\u1ee9 B\u1ea3y.\n        </p>\n\n    </div>\n\n\n    <div class=\"gd-room-grid\">\n\n\n        <!-- =================================================\n             H\u00d2A B\u00ccNH\n        ================================================== -->\n\n        <article\n            id=\"gdRoomHOABINH\"\n            class=\"gd-room\"\n        >\n\n            <div class=\"gd-room-banner\">\n\n                <img\n                    id=\"gdBannerHOABINH\"\n                    src=\"https://drive.google.com/thumbnail?id=1PP0BBYcma0kFkio87aR4ld6dnuRWyP6o&sz=w1600\"\n                    alt=\"Ph\u00f2ng h\u1ecdc Ho\u00e0 B\u00ecnh\"\n                    loading=\"lazy\"\n                    decoding=\"async\"\n                />\n\n            </div>\n\n\n            <div class=\"gd-room-body\">\n\n                <div class=\"gd-room-top\">\n\n                    <div class=\"gd-room-identity\">\n\n                        <div\n                            class=\"gd-room-icon\"\n                            id=\"gdRoomIconHOABINH\"\n                        ></div>\n\n                        <div>\n\n                            <div class=\"gd-room-label\">\n                                PH\u00d2NG H\u1eccC\n                            </div>\n\n                            <h3 class=\"gd-room-name\">\n                                Ph\u00f2ng h\u1ecdc Ho\u00e0 B\u00ecnh\n                            </h3>\n\n                        </div>\n\n                    </div>\n\n\n                    <div>\n\n                        <div\n                            id=\"gdStatusHOABINH\"\n                            class=\"gd-room-status\"\n                        >\n                            <span class=\"gd-room-status-dot\"></span>\n\n                            <span id=\"gdStatusTextHOABINH\">\n                                \u0110ANG KI\u1ec2M TRA\n                            </span>\n                        </div>\n\n\n                        <div class=\"gd-room-schedule\">\n                            Th\u1ee9 S\u00e1u \u2022 19:00\u201321:00\n                        </div>\n\n                    </div>\n\n                </div>\n\n\n                <div class=\"gd-room-note\">\n                    Kh\u00f4ng gian h\u1ecdc th\u01b0 ph\u00e1p d\u00e0nh cho h\u1ecdc vi\u00ean\n                    c\u00e1c kh\u00f3a \u0111\u01b0\u1ee3c ph\u00e2n v\u00e0o Ph\u00f2ng h\u1ecdc Ho\u00e0 B\u00ecnh.\n                </div>\n\n\n                <label\n                    class=\"gd-verify-label\"\n                    for=\"gdCodeHOABINH\"\n                >\n                    Ki\u1ec3m tra M\u00e3 h\u1ecdc vi\u00ean\n                </label>\n\n\n                <div class=\"gd-verify-row\">\n\n                    <input\n                        id=\"gdCodeHOABINH\"\n                        class=\"gd-code-input\"\n                        type=\"text\"\n                        inputmode=\"text\"\n                        autocomplete=\"off\"\n                        autocorrect=\"off\"\n                        autocapitalize=\"characters\"\n                        spellcheck=\"false\"\n                        placeholder=\"Nh\u1eadp M\u00e3 h\u1ecdc vi\u00ean...\"\n                    />\n\n\n                    <button\n                        id=\"gdVerifyHOABINH\"\n                        class=\"gd-verify-button\"\n                        type=\"button\"\n                    >\n                        KI\u1ec2M TRA\n                    </button>\n\n                </div>\n\n\n                <div\n                    id=\"gdMessageHOABINH\"\n                    class=\"gd-room-message\"\n                    aria-live=\"polite\"\n                ></div>\n\n\n                <div\n                    id=\"gdMeetAccessHOABINH\"\n                    class=\"gd-meet-access\"\n                ></div>\n\n            </div>\n\n        </article>\n\n\n\n        <!-- =================================================\n             H\u1ea0NH PH\u00daC\n        ================================================== -->\n\n        <article\n            id=\"gdRoomHANHPHUC\"\n            class=\"gd-room\"\n        >\n\n            <div class=\"gd-room-banner\">\n\n                <img\n                    id=\"gdBannerHANHPHUC\"\n                    src=\"https://drive.google.com/thumbnail?id=19GZP-3tKYLVE2l6uVeihhpnfVKAKaRE4&sz=w1600\"\n                    alt=\"Ph\u00f2ng h\u1ecdc H\u1ea1nh Ph\u00fac\"\n                    loading=\"lazy\"\n                    decoding=\"async\"\n                />\n\n            </div>\n\n\n            <div class=\"gd-room-body\">\n\n                <div class=\"gd-room-top\">\n\n                    <div class=\"gd-room-identity\">\n\n                        <div\n                            class=\"gd-room-icon\"\n                            id=\"gdRoomIconHANHPHUC\"\n                        ></div>\n\n                        <div>\n\n                            <div class=\"gd-room-label\">\n                                PH\u00d2NG H\u1eccC\n                            </div>\n\n                            <h3 class=\"gd-room-name\">\n                                Ph\u00f2ng h\u1ecdc H\u1ea1nh Ph\u00fac\n                            </h3>\n\n                        </div>\n\n                    </div>\n\n\n                    <div>\n\n                        <div\n                            id=\"gdStatusHANHPHUC\"\n                            class=\"gd-room-status\"\n                        >\n                            <span class=\"gd-room-status-dot\"></span>\n\n                            <span id=\"gdStatusTextHANHPHUC\">\n                                \u0110ANG KI\u1ec2M TRA\n                            </span>\n                        </div>\n\n\n                        <div class=\"gd-room-schedule\">\n                            Th\u1ee9 B\u1ea3y \u2022 19:00\u201321:00\n                        </div>\n\n                    </div>\n\n                </div>\n\n\n                <div class=\"gd-room-note\">\n                    Kh\u00f4ng gian h\u1ecdc th\u01b0 ph\u00e1p d\u00e0nh cho h\u1ecdc vi\u00ean\n                    \u0111\u01b0\u1ee3c ph\u00e2n v\u00e0o Ph\u00f2ng h\u1ecdc H\u1ea1nh Ph\u00fac.\n                </div>\n\n\n                <label\n                    class=\"gd-verify-label\"\n                    for=\"gdCodeHANHPHUC\"\n                >\n                    Ki\u1ec3m tra M\u00e3 h\u1ecdc vi\u00ean\n                </label>\n\n\n                <div class=\"gd-verify-row\">\n\n                    <input\n                        id=\"gdCodeHANHPHUC\"\n                        class=\"gd-code-input\"\n                        type=\"text\"\n                        inputmode=\"text\"\n                        autocomplete=\"off\"\n                        autocorrect=\"off\"\n                        autocapitalize=\"characters\"\n                        spellcheck=\"false\"\n                        placeholder=\"Nh\u1eadp M\u00e3 h\u1ecdc vi\u00ean...\"\n                    />\n\n\n                    <button\n                        id=\"gdVerifyHANHPHUC\"\n                        class=\"gd-verify-button\"\n                        type=\"button\"\n                    >\n                        KI\u1ec2M TRA\n                    </button>\n\n                </div>\n\n\n                <div\n                    id=\"gdMessageHANHPHUC\"\n                    class=\"gd-room-message\"\n                    aria-live=\"polite\"\n                ></div>\n\n\n                <div\n                    id=\"gdMeetAccessHANHPHUC\"\n                    class=\"gd-meet-access\"\n                ></div>\n\n            </div>\n\n        </article>\n\n    </div>\n\n\n\n    <!-- =====================================================\n         PH\u00d2NG THI T\u1ed0T NGHI\u1ec6P\n    ====================================================== -->\n\n    <div class=\"gd-graduation-room\">\n\n        <div\n            class=\"gd-graduation-icon\"\n            id=\"gdGraduationIcon\"\n        ></div>\n\n\n        <div>\n\n            <div class=\"gd-graduation-label\">\n                K\u1ef2 THI T\u1ed0T NGHI\u1ec6P\n            </div>\n\n            <h3 class=\"gd-graduation-title\">\n                Ph\u00f2ng Thi T\u1ed1t Nghi\u1ec7p\n            </h3>\n\n            <p class=\"gd-graduation-desc\">\n                Khu v\u1ef1c d\u00e0nh cho h\u1ecdc vi\u00ean \u0111\u1ee7 \u0111i\u1ec1u ki\u1ec7n tham gia\n                k\u1ef3 thi t\u1ed1t nghi\u1ec7p OCD.\n            </p>\n\n        </div>\n\n\n        <a\n            class=\"gd-graduation-button\"\n            href=\"https://www.thudao.com/p/ocd-phong-thi-tot-nghiep-graduation.html\"\n        >\n            V\u00c0O PH\u00d2NG THI\n        </a>\n\n    </div>\n\n\n    <!-- =====================================================\n         PH\u00d2NG LUY\u1ec6N C\u00d4NG\n    ====================================================== -->\n\n    <div class=\"gd-graduation-room gd-practice-room\">\n\n        <div\n            class=\"gd-graduation-icon\"\n            id=\"gdPracticeIcon\"\n        ></div>\n\n\n        <div>\n\n            <div class=\"gd-graduation-label\">\n                LUY\u1ec6N T\u1eacP NH\u00d3M\n            </div>\n\n            <h3 class=\"gd-graduation-title\">\n                Ph\u00f2ng Luy\u1ec7n C\u00f4ng\n            </h3>\n\n            <p class=\"gd-graduation-desc\">\n                C\u00f9ng \u0111\u1ed3ng m\u00f4n v\u00e0o ph\u00f2ng, l\u00e0m b\u1ed9 \u0111\u1ec1 ri\u00eang\n                v\u00e0 nh\u1eadn th\u01b0\u1edfng theo th\u00e0nh t\u00edch chung.\n            </p>\n\n        </div>\n\n\n        <a\n            class=\"gd-graduation-button gd-practice-button\"\n            href=\"https://www.thudao.com/p/luyen-cong.html\"\n        >\n            V\u00c0O PH\u00d2NG LUY\u1ec6N C\u00d4NG\n        </a>\n\n    </div>\n\n\n\n    <div class=\"gd-privacy-note\">\n\n        <span id=\"gdPrivacyIcon\"></span>\n\n        <span>\n            M\u00e3 h\u1ecdc vi\u00ean ch\u1ec9 d\u00f9ng \u0111\u1ec3 x\u00e1c minh quy\u1ec1n v\u00e0o l\u1edbp.\n            Gi\u1ea3ng \u0111\u01b0\u1eddng kh\u00f4ng c\u00f4ng khai m\u00e3 h\u1ecdc vi\u00ean,\n            \u0111i\u1ec3m s\u1ed1 ho\u1eb7c n\u1ed9i dung nh\u1eadn x\u00e9t.\n        </span>\n\n    </div>\n\n</section>\n\n\n\n<!-- =========================================================\n     ACTIVITY\n========================================================= -->\n\n<section class=\"gd-section gd-lammo-section\">\n\n    <div class=\"gd-section-heading\">\n\n        <div class=\"gd-section-kicker\">\n            NH\u1ecaP S\u1ed0NG L\u1edaP H\u1eccC\n        </div>\n\n        <h2 class=\"gd-section-title\">\n            \u0110\u00f3ng g\u00f3p Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4\n        </h2>\n\n        <p class=\"gd-section-desc\">\n            Nh\u1eefng b\u1ea3n l\u00e2m h\u1ecdc vi\u00ean v\u1eeba g\u00f3p v\u00e0o Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4, k\u00e8m l\u01b0\u1ee3t th\u1ea3 tim c\u1ee7a \u0111\u1ed3ng m\u00f4n.\n        </p>\n\n    </div>\n\n    <div class=\"gd-activity-card\">\n\n        <div class=\"gd-activity-toolbar gd-lammo-toolbar\">\n\n            <div class=\"gd-lammo-intro\">\n                G\u00f3p b\u1ea3n l\u00e2m c\u1ee7a b\u1ea1n \u0111\u1ec3 \u0111\u1ed3ng m\u00f4n c\u00f9ng h\u1ecdc v\u00e0 th\u1ea3 tim.\n            </div>\n\n            <div class=\"gd-lammo-actions\">\n\n                <a\n                    id=\"gdLamMoCta\"\n                    class=\"gd-lammo-cta\"\n                    href=\"https://www.thudao.com/p/thu-vien-lam-mo.html\"\n                >\n                    \u270d \u0110\u00f3ng g\u00f3p ngay\n                </a>\n\n                <button\n                    id=\"gdRefreshActivity\"\n                    class=\"gd-refresh-button\"\n                    type=\"button\"\n                >\n                    \u21bb M\u1edbi\n                </button>\n\n            </div>\n\n        </div>\n\n        <div\n            id=\"gdActivityFeed\"\n            class=\"gd-activity-feed gd-lammo-grid\"\n        >\n            <div class=\"gd-empty\">\n                \u0110ang t\u1ea3i b\u1ea3n l\u00e2m m\u1edbi \u0111\u00f3ng g\u00f3p...\n            </div>\n        </div>\n\n        <div\n            id=\"gdLamMoStatus\"\n            class=\"gd-lammo-status\"\n            aria-live=\"polite\"\n        ></div>\n\n        <div\n            id=\"gdLoadMoreWrap\"\n            class=\"gd-load-more-wrap\"\n        >\n            <button\n                id=\"gdLoadMore\"\n                class=\"gd-load-more\"\n                type=\"button\"\n            >\n                XEM TH\u00caM B\u1ea2N L\u00c2M\n            </button>\n        </div>\n\n    </div>\n\n</section>\n\n</div>\n\n\n\n<script>\n(function(){\n\n\"use strict\";\n\n\n/* =========================================================\n   GI\u1ea2NG \u0110\u01af\u1edcNG OCD\n   LECTURE HALL v1.7.0\n   + TRANSITIONAL IDENTITY\n   + MINH H\u1ed2NG CONTEXT\n\n   GI\u1eee NGUY\u00caN:\n   - Ph\u00f2ng h\u1ecdc Ho\u00e0 B\u00ecnh\n   - Ph\u00f2ng h\u1ecdc H\u1ea1nh Ph\u00fac\n   - Ph\u00f2ng Thi T\u1ed1t Nghi\u1ec7p\n   - Ho\u1ea1t \u0111\u1ed9ng g\u1ea7n \u0111\u00e2y\n   - M\u00e3 \u01b0u ti\u00ean Goiungho800k / MaHocVien\n\n   \u0110\u1ecaNH DANH:\n   1. M\u00e3 \u01b0u ti\u00ean -> \u0111\u01b0\u1ee3c v\u00e0o c\u1ea3 hai ph\u00f2ng\n   2. HocVien -> ngu\u1ed3n \u0111\u1ecbnh danh ch\u00ednh\n   3. Ch\u01b0a c\u00f3 HocVien -> fallback XepHang\n   4. HocVien l\u1ed7i -> FAIL CLOSED\n   5. HocVien \u0111\u00e3 c\u00f3 m\u00e3 -> tr\u1ea1ng th\u00e1i HocVien quy\u1ebft \u0111\u1ecbnh\n\n   PH\u00c2N PH\u00d2NG:\n   - Ho\u00e0 B\u00ecnh: 01 / 02 / 03\n   - H\u1ea1nh Ph\u00fac: 01 / 02 / 03 / 04\n\n   L\u1ecaCH:\n   - Ho\u00e0 B\u00ecnh: Th\u1ee9 S\u00e1u 19:00\u201321:00\n   - H\u1ea1nh Ph\u00fac: Th\u1ee9 B\u1ea3y 19:00\u201321:00\n\n   MINH H\u1ed2NG:\n   - page = GiangDuong\n   - Kh\u00f4ng fetch th\u00eam d\u1eef li\u1ec7u\n   - X\u00e1c minh th\u00e0nh c\u00f4ng -> confirmStudent\n   - \u0110\u1ed3ng b\u1ed9 \u0111\u00fang/sai ph\u00f2ng\n   - \u0110\u1ed3ng b\u1ed9 gi\u1edd h\u1ecdc\n   - \u0110\u1ed3ng b\u1ed9 Meet\n========================================================= */\n\n\n/* =========================================================\n   CONFIG\n========================================================= */\n\nconst CONFIG={\n\n    hoaBinhMeetUrl:\n        \"https://meet.google.com/qoj-ozun-eyc\",\n\n    hanhPhucMeetUrl:\n        \"https://meet.google.com/qoj-ozun-eyc\",\n\n\n    graduationExamUrl:\n        \"https://www.thudao.com/p/ocd-phong-thi-tot-nghiep-graduation.html\",\n\n\n    practiceRoomUrl:\n        \"https://www.thudao.com/p/luyen-cong.html\",\n\n\n    banners:{\n\n        HOABINH:\n            \"https://drive.google.com/thumbnail?id=\" +\n            \"1PP0BBYcma0kFkio87aR4ld6dnuRWyP6o\" +\n            \"&sz=w1600\",\n\n        HANHPHUC:\n            \"https://drive.google.com/thumbnail?id=\" +\n            \"19GZP-3tKYLVE2l6uVeihhpnfVKAKaRE4\" +\n            \"&sz=w1600\"\n\n    },\n\n\n    /* =====================================================\n       HOCVIEN\n    ===================================================== */\n\n    studentDirectoryCsv:\n\n        \"https://docs.google.com/spreadsheets/d/e/\" +\n\n        \"2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/\" +\n\n        \"pub?gid=1603096683&single=true&output=csv\",\n\n\n    /* =====================================================\n       XEPHANG FALLBACK\n    ===================================================== */\n\n    legacyDirectoryCsv:\n\n        \"https://docs.google.com/spreadsheets/d/e/\" +\n\n        \"2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/\" +\n\n        \"pub?gid=1326884435&single=true&output=csv\",\n\n\n    /* =====================================================\n       M\u00c3 \u01afU TI\u00caN\n    ===================================================== */\n\n    prioritySpreadsheetId:\n        \"1hLNi_OP6ScSz8OUH-Qj7qc5LTTPAHevZQg9MvFBvVro\",\n\n    prioritySheetName:\n        \"MaHocVien\",\n\n\n    /* =====================================================\n       ACTIVITY\n    ===================================================== */\n\n    submissionCsv:\n\n        \"https://docs.google.com/spreadsheets/d/e/\" +\n\n        \"2PACX-1vRP5cc8duj1XrCXMrymo6Cj7aqIkWfX6bHxGeW-lXcSewfQXhM8fZ5rzbNIQ9mBeVuB8yYr_o1aBoYA/\" +\n\n        \"pub?output=csv\",\n\n\n    rewardSpreadsheetId:\n        \"1-IkcpEkKQtIavl5DIf6Sbwx3p0aAfnSS4HjT6dn1u_E\",\n\n    teacherGiftSheetName:\n        \"QuaTangGVCN\",\n\n\n    /* =====================================================\n       PH\u00d2NG\n    ===================================================== */\n\n    rooms:{\n\n        HOABINH:{\n\n            allowedSuffixes:[\n                \"01\",\n                \"02\",\n                \"03\"\n            ],\n\n            displayName:\n                \"Ph\u00f2ng h\u1ecdc Ho\u00e0 B\u00ecnh\"\n        },\n\n        HANHPHUC:{\n\n            allowedSuffixes:[\n                \"01\",\n                \"02\",\n                \"03\",\n                \"04\"\n            ],\n\n            displayName:\n                \"Ph\u00f2ng h\u1ecdc H\u1ea1nh Ph\u00fac\"\n        }\n\n    },\n\n\n    /* =====================================================\n       L\u1ecaCH\n    ===================================================== */\n\n    schedules:{\n\n        HOABINH:{\n\n            dayOfWeek:5,\n\n            startHour:19,\n            startMinute:0,\n\n            endHour:21,\n            endMinute:0\n        },\n\n        HANHPHUC:{\n\n            dayOfWeek:6,\n\n            startHour:19,\n            startMinute:0,\n\n            endHour:21,\n            endMinute:0\n        }\n\n    },\n\n\n    timeZone:\n        \"Asia/Ho_Chi_Minh\",\n\n\n    liveMeetStatus:{\n\n        enabled:false,\n\n        endpoint:\"\",\n\n        refreshInterval:\n            60000\n    },\n\n\n    activityPageSize:\n        8,\n\n    maxActivities:\n        80,\n\n    activityRefreshInterval:\n        120000,\n\n    requestTimeout:\n        12000\n\n};\n\n\n\n/* =========================================================\n   ICON\n========================================================= */\n\nconst ICON={\n\n    roomHoaBinh:\n        String.fromCodePoint(\n            0x1F54A,\n            0xFE0F\n        ),\n\n    roomHanhPhuc:\n        String.fromCodePoint(\n            0x1F338\n        ),\n\n    graduation:\n        String.fromCodePoint(\n            0x1F393\n        ),\n\n    practice:\n        String.fromCodePoint(\n            0x1F94B\n        ),\n\n    lock:\n        String.fromCodePoint(\n            0x1F510\n        ),\n\n    submission:\n        String.fromCodePoint(\n            0x1F4DD\n        ),\n\n    grade:\n        String.fromCodePoint(\n            0x270D,\n            0xFE0F\n        ),\n\n    comment:\n        String.fromCodePoint(\n            0x1F4AC\n        ),\n\n    gift:\n        String.fromCodePoint(\n            0x1F381\n        ),\n\n    video:\n        String.fromCodePoint(\n            0x1F3A5\n        ),\n\n    check:\n        String.fromCodePoint(\n            0x2713\n        ),\n\n    book:\n        String.fromCodePoint(\n            0x1F4DA\n        )\n\n};\n\n\n\nconst CHAR={\n\n    dash:\n        String.fromCodePoint(\n            0x2013\n        ),\n\n    bullet:\n        String.fromCodePoint(\n            0x2022\n        )\n\n};\n\n\n\n/* =========================================================\n   STATE\n========================================================= */\n\nconst state={\n\n    directory:null,\n    directoryPromise:null,\n\n    legacyDirectory:null,\n    legacyDirectoryPromise:null,\n\n    priorityCodes:null,\n    priorityPromise:null,\n\n    activities:[],\n\n    activityFilter:\"all\",\n\n    visibleActivityCount:\n        CONFIG.activityPageSize,\n\n    loadingActivity:false,\n\n    activityTimer:null,\n\n    statusTimer:null\n\n};\n\n\n\n/* =========================================================\n   MINH H\u1ed2NG STATE\n========================================================= */\n\nconst minhHongState={\n\n    studentCode:\"\",\n    studentName:\"\",\n    group:\"\",\n    course:\"\",\n    studentStatus:\"\",\n\n    identitySource:\"\",\n\n    priorityStudent:false,\n\n    selectedRoom:\"\",\n    assignedRoom:\"\",\n\n    verified:false,\n\n    correctRoom:false,\n    wrongRoom:false,\n\n    accessGranted:false,\n\n    roomLive:false,\n    meetReady:false,\n\n    lastReason:\"\"\n\n};\n\n\n\n/* =========================================================\n   BASIC\n========================================================= */\n\nfunction el(id){\n\n    return document.getElementById(\n        id\n    );\n}\n\n\n\nfunction clean(value){\n\n    return String(\n        value === undefined ||\n        value === null\n        ?\n        \"\"\n        :\n        value\n    )\n    .trim();\n}\n\n\n\nfunction normalizeText(value){\n\n    return clean(value)\n\n    .toLowerCase()\n\n    .normalize(\"NFD\")\n\n    .replace(\n        /[\\u0300-\\u036f]/g,\n        \"\"\n    )\n\n    .replace(\n        /\u0111/g,\n        \"d\"\n    )\n\n    .replace(\n        /\\s+/g,\n        \" \"\n    );\n}\n\n\n\nfunction normalizeCode(value){\n\n    return clean(value)\n\n    .toUpperCase()\n\n    .replace(\n        /\\s+/g,\n        \"\"\n    );\n}\n\n\n\nfunction normalizeStatus(value){\n\n    return normalizeCode(\n        value\n    );\n}\n\n\n\n/* =========================================================\n   INITIAL UI\n========================================================= */\n\nfunction initUI(){\n\n    if(el(\"gdRoomIconHOABINH\")){\n\n        el(\"gdRoomIconHOABINH\").textContent=\n            ICON.roomHoaBinh;\n    }\n\n\n    if(el(\"gdRoomIconHANHPHUC\")){\n\n        el(\"gdRoomIconHANHPHUC\").textContent=\n            ICON.roomHanhPhuc;\n    }\n\n\n    if(el(\"gdGraduationIcon\")){\n\n        el(\"gdGraduationIcon\").textContent=\n            ICON.graduation;\n    }\n\n\n    if(el(\"gdPracticeIcon\")){\n\n        el(\"gdPracticeIcon\").textContent=\n            ICON.practice;\n    }\n\n\n    if(el(\"gdPrivacyIcon\")){\n\n        el(\"gdPrivacyIcon\").textContent=\n            ICON.lock;\n    }\n\n\n    if(el(\"gdFilterSubmissionIcon\")){\n\n        el(\"gdFilterSubmissionIcon\").textContent=\n            ICON.submission;\n    }\n\n\n    if(el(\"gdFilterGradeIcon\")){\n\n        el(\"gdFilterGradeIcon\").textContent=\n            ICON.grade;\n    }\n\n\n    if(el(\"gdFilterCommentIcon\")){\n\n        el(\"gdFilterCommentIcon\").textContent=\n            ICON.comment;\n    }\n\n\n    if(el(\"gdFilterGiftIcon\")){\n\n        el(\"gdFilterGiftIcon\").textContent=\n            ICON.gift;\n    }\n\n\n    if(el(\"gdBannerHOABINH\")){\n\n        el(\"gdBannerHOABINH\").src=\n            CONFIG.banners.HOABINH;\n    }\n\n\n    if(el(\"gdBannerHANHPHUC\")){\n\n        el(\"gdBannerHANHPHUC\").src=\n            CONFIG.banners.HANHPHUC;\n    }\n\n\n    const graduationButton=\n        document.querySelector(\n            \"#lectureHallPage .gd-graduation-button\"\n        );\n\n\n    if(graduationButton){\n\n        graduationButton.href=\n            CONFIG.graduationExamUrl;\n    }\n\n\n    const practiceButton=\n        document.querySelector(\n            \"#lectureHallPage .gd-practice-button\"\n        );\n\n\n    if(practiceButton){\n\n        practiceButton.href=\n            CONFIG.practiceRoomUrl;\n    }\n\n}\n\n\n\n/* =========================================================\n   CSV\n========================================================= */\n\nfunction parseCSV(text){\n\n    text=\n        String(text || \"\")\n        .replace(\n            /^\\uFEFF/,\n            \"\"\n        );\n\n\n    const rows=[];\n\n    let row=[];\n    let value=\"\";\n    let quoted=false;\n\n\n    for(\n        let i=0;\n        i<text.length;\n        i++\n    ){\n\n        const char=\n            text[i];\n\n\n        if(char === '\"'){\n\n            if(\n                quoted &&\n                text[i+1] === '\"'\n            ){\n\n                value += '\"';\n                i++;\n\n            }else{\n\n                quoted=\n                    !quoted;\n            }\n\n            continue;\n        }\n\n\n        if(\n            char === \",\" &&\n            !quoted\n        ){\n\n            row.push(value);\n\n            value=\"\";\n\n            continue;\n        }\n\n\n        if(\n            (\n                char === \"\\n\" ||\n                char === \"\\r\"\n            )\n            &&\n            !quoted\n        ){\n\n            if(\n                char === \"\\r\" &&\n                text[i+1] === \"\\n\"\n            ){\n\n                i++;\n            }\n\n\n            row.push(value);\n\n\n            if(\n                row.some(\n                    function(cell){\n\n                        return(\n                            clean(cell) !== \"\"\n                        );\n                    }\n                )\n            ){\n\n                rows.push(row);\n            }\n\n\n            row=[];\n            value=\"\";\n\n            continue;\n        }\n\n\n        value += char;\n    }\n\n\n    row.push(value);\n\n\n    if(\n        row.some(\n            function(cell){\n\n                return(\n                    clean(cell) !== \"\"\n                );\n            }\n        )\n    ){\n\n        rows.push(row);\n    }\n\n\n    return rows;\n}\n\n\n\n/* =========================================================\n   COLUMN\n========================================================= */\n\nfunction findColumn(\n    headers,\n    aliases\n){\n\n    const normalized=\n        (headers || [])\n        .map(\n            normalizeText\n        );\n\n\n    for(\n        const alias\n        of aliases\n    ){\n\n        const wanted=\n            normalizeText(alias);\n\n\n        const exact=\n            normalized.indexOf(\n                wanted\n            );\n\n\n        if(exact >= 0){\n\n            return exact;\n        }\n    }\n\n\n    for(\n        const alias\n        of aliases\n    ){\n\n        const wanted=\n            normalizeText(alias);\n\n\n        const found=\n            normalized.findIndex(\n                function(header){\n\n                    return(\n                        header &&\n                        header.includes(\n                            wanted\n                        )\n                    );\n                }\n            );\n\n\n        if(found >= 0){\n\n            return found;\n        }\n    }\n\n\n    return -1;\n}\n\n\n\n/* =========================================================\n   FETCH\n========================================================= */\n\nasync function fetchText(url){\n\n    const controller=\n        typeof AbortController !==\n        \"undefined\"\n        ?\n        new AbortController()\n        :\n        null;\n\n\n    const timer=\n        controller\n        ?\n        setTimeout(\n            function(){\n\n                controller.abort();\n\n            },\n            CONFIG.requestTimeout\n        )\n        :\n        null;\n\n\n    try{\n\n        const response=\n            await fetch(\n                url,\n                {\n                    cache:\"no-store\",\n\n                    signal:\n                        controller\n                        ?\n                        controller.signal\n                        :\n                        undefined\n                }\n            );\n\n\n        if(!response.ok){\n\n            throw new Error(\n                \"HTTP \" +\n                response.status\n            );\n        }\n\n\n        return await response.text();\n\n\n    }finally{\n\n        if(timer){\n\n            clearTimeout(timer);\n        }\n    }\n}\n\n\n\n/* =========================================================\n   HOCVIEN\n========================================================= */\n\nfunction detectDirectoryColumns(headers){\n\n    return{\n\n        code:\n            findColumn(\n                headers,\n                [\n                    \"M\u00e3 h\u1ecdc vi\u00ean\",\n                    \"Ma hoc vien\",\n                    \"M\u00e3 HV\",\n                    \"Ma HV\",\n                    \"S\u1ed1 b\u00e1o danh\",\n                    \"So bao danh\",\n                    \"SBD\"\n                ]\n            ),\n\n        name:\n            findColumn(\n                headers,\n                [\n                    \"H\u1ecd v\u00e0 t\u00ean\",\n                    \"Ho va ten\",\n                    \"H\u1ecd t\u00ean\",\n                    \"Ho ten\",\n                    \"T\u00ean h\u1ecdc vi\u00ean\",\n                    \"Ten hoc vien\"\n                ]\n            ),\n\n        group:\n            findColumn(\n                headers,\n                [\n                    \"T\u1ed5\",\n                    \"To\"\n                ]\n            ),\n\n        course:\n            findColumn(\n                headers,\n                [\n                    \"Kho\u00e1\",\n                    \"Kh\u00f3a\",\n                    \"Khoa\"\n                ]\n            ),\n\n        status:\n            findColumn(\n                headers,\n                [\n                    \"Tr\u1ea1ng th\u00e1i\",\n                    \"Trang thai\",\n                    \"Status\"\n                ]\n            )\n\n    };\n}\n\n\n\nfunction mapDirectoryRows(rows){\n\n    const result=\n        new Map();\n\n\n    if(\n        !rows ||\n        rows.length < 2\n    ){\n\n        return result;\n    }\n\n\n    const columns=\n        detectDirectoryColumns(\n            rows[0]\n        );\n\n\n    if(columns.code < 0){\n\n        throw new Error(\n            \"Kh\u00f4ng t\u00ecm th\u1ea5y c\u1ed9t M\u00e3 h\u1ecdc vi\u00ean trong HocVien.\"\n        );\n    }\n\n\n    for(\n        let i=1;\n        i<rows.length;\n        i++\n    ){\n\n        const row=\n            rows[i];\n\n\n        const code=\n            normalizeCode(\n                row[columns.code]\n            );\n\n\n        if(!code){\n\n            continue;\n        }\n\n\n        result.set(\n            code,\n            {\n\n                code:code,\n\n                name:\n                    columns.name >= 0\n                    ?\n                    clean(\n                        row[columns.name]\n                    )\n                    :\n                    \"\",\n\n                group:\n                    columns.group >= 0\n                    ?\n                    clean(\n                        row[columns.group]\n                    )\n                    :\n                    \"\",\n\n                course:\n                    columns.course >= 0\n                    ?\n                    clean(\n                        row[columns.course]\n                    )\n                    :\n                    \"\",\n\n                status:\n                    columns.status >= 0\n                    ?\n                    normalizeStatus(\n                        row[columns.status]\n                    )\n                    :\n                    \"\",\n\n                legacy:false\n\n            }\n        );\n    }\n\n\n    return result;\n}\n\n\n\nasync function loadDirectory(){\n\n    if(state.directory){\n\n        return state.directory;\n    }\n\n\n    if(state.directoryPromise){\n\n        return state.directoryPromise;\n    }\n\n\n    state.directoryPromise=\n        (async function(){\n\n            const text=\n                await fetchText(\n                    CONFIG.studentDirectoryCsv\n                );\n\n\n            const directory=\n                mapDirectoryRows(\n                    parseCSV(text)\n                );\n\n\n            if(!directory.size){\n\n                throw new Error(\n                    \"Danh s\u00e1ch HocVien tr\u1ed1ng.\"\n                );\n            }\n\n\n            state.directory=\n                directory;\n\n\n            return directory;\n\n        })();\n\n\n    try{\n\n        return await state.directoryPromise;\n\n    }finally{\n\n        state.directoryPromise=\n            null;\n    }\n}\n\n\n\n/* =========================================================\n   XEPHANG LEGACY\n========================================================= */\n\nfunction detectLegacyDirectoryColumns(headers){\n\n    return{\n\n        code:\n            findColumn(\n                headers,\n                [\n                    \"M\u00e3 h\u1ecdc vi\u00ean\",\n                    \"Ma hoc vien\",\n                    \"M\u00e3 HV\",\n                    \"Ma HV\",\n                    \"S\u1ed1 b\u00e1o danh\",\n                    \"So bao danh\",\n                    \"SBD\"\n                ]\n            ),\n\n        name:\n            findColumn(\n                headers,\n                [\n                    \"H\u1ecd v\u00e0 t\u00ean\",\n                    \"Ho va ten\",\n                    \"H\u1ecd t\u00ean\",\n                    \"Ho ten\",\n                    \"T\u00ean h\u1ecdc vi\u00ean\",\n                    \"Ten hoc vien\"\n                ]\n            )\n\n    };\n}\n\n\n\nfunction mapLegacyDirectoryRows(rows){\n\n    const result=\n        new Map();\n\n\n    if(\n        !rows ||\n        rows.length < 2\n    ){\n\n        return result;\n    }\n\n\n    const columns=\n        detectLegacyDirectoryColumns(\n            rows[0]\n        );\n\n\n    if(columns.code < 0){\n\n        throw new Error(\n            \"Kh\u00f4ng t\u00ecm th\u1ea5y c\u1ed9t M\u00e3 h\u1ecdc vi\u00ean trong XepHang.\"\n        );\n    }\n\n\n    for(\n        let i=1;\n        i<rows.length;\n        i++\n    ){\n\n        const row=\n            rows[i];\n\n\n        const code=\n            normalizeCode(\n                row[columns.code]\n            );\n\n\n        if(!code){\n\n            continue;\n        }\n\n\n        result.set(\n            code,\n            {\n\n                code:code,\n\n                name:\n                    columns.name >= 0\n                    ?\n                    clean(\n                        row[columns.name]\n                    )\n                    :\n                    \"\",\n\n                group:\"\",\n                course:\"\",\n                status:\"\",\n\n                legacy:true\n\n            }\n        );\n    }\n\n\n    return result;\n}\n\n\n\nasync function loadLegacyDirectory(){\n\n    if(state.legacyDirectory){\n\n        return state.legacyDirectory;\n    }\n\n\n    if(state.legacyDirectoryPromise){\n\n        return state.legacyDirectoryPromise;\n    }\n\n\n    state.legacyDirectoryPromise=\n        (async function(){\n\n            const text=\n                await fetchText(\n                    CONFIG.legacyDirectoryCsv\n                );\n\n\n            const directory=\n                mapLegacyDirectoryRows(\n                    parseCSV(text)\n                );\n\n\n            state.legacyDirectory=\n                directory;\n\n\n            return directory;\n\n        })();\n\n\n    try{\n\n        return await state.legacyDirectoryPromise;\n\n    }finally{\n\n        state.legacyDirectoryPromise=\n            null;\n    }\n}\n\n\n\n/* =========================================================\n   STATUS HOCVIEN\n========================================================= */\n\nfunction getStudentStatusMessage(student){\n\n    if(!student){\n\n        return{\n            allowed:false,\n            type:\"error\",\n            text:\n                \"Kh\u00f4ng t\u00ecm th\u1ea5y M\u00e3 h\u1ecdc vi\u00ean n\u00e0y trong h\u1ec7 th\u1ed1ng.\"\n        };\n    }\n\n\n    const status=\n        normalizeStatus(\n            student.status\n        );\n\n\n    /*\n       ACTIVE ho\u1eb7c \u00f4 tr\u1ea1ng th\u00e1i tr\u1ed1ng\n       \u0111\u01b0\u1ee3c ch\u1ea5p nh\u1eadn trong giai \u0111o\u1ea1n chuy\u1ec3n ti\u1ebfp.\n    */\n\n    if(\n        status === \"ACTIVE\" ||\n        status === \"\"\n    ){\n\n        return{\n            allowed:true,\n            type:\"success\",\n            text:\"\"\n        };\n    }\n\n\n    if(status === \"PENDING\"){\n\n        return{\n            allowed:false,\n            type:\"warning\",\n            text:\n                \"M\u00e3 h\u1ecdc vi\u00ean n\u00e0y ch\u01b0a \u0111\u01b0\u1ee3c k\u00edch ho\u1ea1t.\"\n        };\n    }\n\n\n    if(status === \"PAUSED\"){\n\n        return{\n            allowed:false,\n            type:\"warning\",\n            text:\n                \"M\u00e3 h\u1ecdc vi\u00ean n\u00e0y hi\u1ec7n \u0111ang t\u1ea1m d\u1eebng.\"\n        };\n    }\n\n\n    if(status === \"GRADUATED\"){\n\n        return{\n            allowed:false,\n            type:\"warning\",\n            text:\n                \"M\u00e3 h\u1ecdc vi\u00ean n\u00e0y \u0111\u00e3 chuy\u1ec3n sang tr\u1ea1ng th\u00e1i t\u1ed1t nghi\u1ec7p.\"\n        };\n    }\n\n\n    return{\n        allowed:false,\n        type:\"warning\",\n        text:\n            \"M\u00e3 h\u1ecdc vi\u00ean hi\u1ec7n kh\u00f4ng \u1edf tr\u1ea1ng th\u00e1i ho\u1ea1t \u0111\u1ed9ng.\"\n    };\n}\n\n\n\n/* =========================================================\n   PRIORITY\n========================================================= */\n\nfunction priorityCsvUrl(){\n\n    return(\n\n        \"https://docs.google.com/spreadsheets/d/\"\n\n        +\n\n        CONFIG.prioritySpreadsheetId\n\n        +\n\n        \"/gviz/tq?tqx=out:csv&sheet=\"\n\n        +\n\n        encodeURIComponent(\n            CONFIG.prioritySheetName\n        )\n\n        +\n\n        \"&cb=\"\n\n        +\n\n        Date.now()\n\n    );\n}\n\n\n\nfunction mapPriorityCodes(rows){\n\n    const result=\n        new Set();\n\n\n    const ignoredHeaders=\n        new Set([\n            \"MAHOCVIEN\",\n            \"MAHV\",\n            \"SBD\",\n            \"SOBAODANH\",\n            \"STT\",\n            \"HOTEN\",\n            \"HOVATEN\"\n        ]);\n\n\n    (rows || [])\n    .forEach(\n        function(row){\n\n            (row || [])\n            .forEach(\n                function(cell){\n\n                    const value=\n                        normalizeCode(cell);\n\n\n                    if(!value){\n\n                        return;\n                    }\n\n\n                    const headerKey=\n                        normalizeText(value)\n\n                        .replace(\n                            /[^a-z0-9]/g,\n                            \"\"\n                        )\n\n                        .toUpperCase();\n\n\n                    if(\n                        ignoredHeaders.has(\n                            headerKey\n                        )\n                    ){\n\n                        return;\n                    }\n\n\n                    result.add(value);\n\n                }\n            );\n\n        }\n    );\n\n\n    return result;\n}\n\n\n\nasync function loadPriorityCodes(){\n\n    if(state.priorityCodes){\n\n        return state.priorityCodes;\n    }\n\n\n    if(state.priorityPromise){\n\n        return state.priorityPromise;\n    }\n\n\n    state.priorityPromise=\n        (async function(){\n\n            const text=\n                await fetchText(\n                    priorityCsvUrl()\n                );\n\n\n            const codes=\n                mapPriorityCodes(\n                    parseCSV(text)\n                );\n\n\n            state.priorityCodes=\n                codes;\n\n\n            return codes;\n\n        })();\n\n\n    try{\n\n        return await state.priorityPromise;\n\n    }finally{\n\n        state.priorityPromise=\n            null;\n    }\n}\n\n\n\nasync function isPriorityStudent(code){\n\n    code=\n        normalizeCode(code);\n\n\n    if(!code){\n\n        return false;\n    }\n\n\n    try{\n\n        const codes=\n            await loadPriorityCodes();\n\n\n        return codes.has(code);\n\n\n    }catch(error){\n\n        console.warn(\n            \"[Giang Duong Priority]\",\n            error\n        );\n\n\n        return false;\n    }\n}\n\n\n\n/* =========================================================\n   PH\u00c2N PH\u00d2NG\n========================================================= */\n\nfunction roomForCode(code, preferredRoom){\n\n    code=\n        normalizeCode(code);\n\n\n    if(\n        preferredRoom ===\n        \"HANHPHUC\" &&\n        CONFIG.rooms.HANHPHUC\n        .allowedSuffixes\n        .some(\n            function(suffix){\n                return code.endsWith(\n                    suffix\n                );\n            }\n        )\n    ){\n        return \"HANHPHUC\";\n    }\n    const hoaBinh=\n        CONFIG.rooms\n        .HOABINH\n        .allowedSuffixes\n        .some(\n            function(suffix){\n\n                return code.endsWith(\n                    suffix\n                );\n            }\n        );\n\n\n    if(hoaBinh){\n\n        return \"HOABINH\";\n    }\n\n\n    const hanhPhuc=\n        CONFIG.rooms\n        .HANHPHUC\n        .allowedSuffixes\n        .some(\n            function(suffix){\n\n                return code.endsWith(\n                    suffix\n                );\n            }\n        );\n\n\n    if(hanhPhuc){\n\n        return \"HANHPHUC\";\n    }\n\n\n    return \"\";\n}\n\n\n\n/* =========================================================\n   VIETNAM TIME\n========================================================= */\n\nfunction getVietnamTime(){\n\n    const parts=\n        new Intl.DateTimeFormat(\n            \"en-US\",\n            {\n                timeZone:\n                    CONFIG.timeZone,\n\n                weekday:\n                    \"short\",\n\n                hour:\n                    \"2-digit\",\n\n                minute:\n                    \"2-digit\",\n\n                hourCycle:\n                    \"h23\"\n            }\n        )\n        .formatToParts(\n            new Date()\n        );\n\n\n    const data={};\n\n\n    parts.forEach(\n        function(part){\n\n            data[part.type]=\n                part.value;\n        }\n    );\n\n\n    const dayMap={\n\n        Sun:0,\n        Mon:1,\n        Tue:2,\n        Wed:3,\n        Thu:4,\n        Fri:5,\n        Sat:6\n\n    };\n\n\n    return{\n\n        day:\n            dayMap[data.weekday],\n\n        hour:\n            Number(data.hour),\n\n        minute:\n            Number(data.minute)\n\n    };\n}\n\n\n\n/* =========================================================\n   SCHEDULE\n========================================================= */\n\nfunction isRoomScheduledLive(room){\n\n    const schedule=\n        CONFIG.schedules[room];\n\n\n    const now=\n        getVietnamTime();\n\n\n    if(\n        now.day !==\n        schedule.dayOfWeek\n    ){\n\n        return false;\n    }\n\n\n    const current=\n        now.hour * 60 +\n        now.minute;\n\n\n    const start=\n        schedule.startHour * 60 +\n        schedule.startMinute;\n\n\n    const end=\n        schedule.endHour * 60 +\n        schedule.endMinute;\n\n\n    return(\n        current >= start &&\n        current < end\n    );\n}\n\n\n\n/* =========================================================\n   REAL MEET STATUS\n========================================================= */\n\nasync function loadRealMeetStatus(){\n\n    if(\n        !CONFIG.liveMeetStatus.enabled ||\n        !CONFIG.liveMeetStatus.endpoint\n    ){\n\n        return null;\n    }\n\n\n    try{\n\n        const text=\n            await fetchText(\n                CONFIG.liveMeetStatus.endpoint\n            );\n\n\n        const data=\n            JSON.parse(text);\n\n\n        return{\n\n            HOABINH:\n                Boolean(data.HOABINH),\n\n            HANHPHUC:\n                Boolean(data.HANHPHUC)\n\n        };\n\n\n    }catch(error){\n\n        return null;\n    }\n}\n\n\n\n/* =========================================================\n   ROOM STATUS\n========================================================= */\n\nfunction setRoomStatus(\n    room,\n    active\n){\n\n    const roomElement=\n        el(\n            \"gdRoom\" +\n            room\n        );\n\n\n    const badge=\n        el(\n            \"gdStatus\" +\n            room\n        );\n\n\n    const text=\n        el(\n            \"gdStatusText\" +\n            room\n        );\n\n\n    if(roomElement){\n\n        roomElement.classList.toggle(\n            \"live\",\n            active\n        );\n    }\n\n\n    if(badge){\n\n        badge.classList.toggle(\n            \"live\",\n            active\n        );\n    }\n\n\n    if(text){\n\n        text.textContent=\n            active\n            ?\n            \"\u0110ANG HO\u1ea0T \u0110\u1ed8NG\"\n            :\n            \"CH\u01afA HO\u1ea0T \u0110\u1ed8NG\";\n    }\n}\n\n\n\n/* =========================================================\n   MINH H\u1ed2NG\n========================================================= */\n\nfunction getMinhHongContextAPI(){\n\n    const api=\n        window.OCDMinhHongContext;\n\n\n    if(\n        api &&\n        typeof api.set === \"function\"\n    ){\n\n        return api;\n    }\n\n\n    return null;\n}\n\n\n\nfunction getMinhHongSessionAPI(){\n\n    const api=\n        window.OCDStudentSession;\n\n\n    if(\n        api &&\n        typeof api.confirmStudent === \"function\"\n    ){\n\n        return api;\n    }\n\n\n    return null;\n}\n\n\n\nfunction confirmMinhHongStudent(code){\n\n    code=\n        normalizeCode(code);\n\n\n    if(!code){\n\n        return;\n    }\n\n\n    const api=\n        getMinhHongSessionAPI();\n\n\n    if(!api){\n\n        return;\n    }\n\n\n    try{\n\n        api.confirmStudent(\n            code,\n            \"GiangDuong\"\n        );\n\n\n    }catch(error){\n\n        console.warn(\n            \"[Giang Duong Minh Hong Session]\",\n            error\n        );\n    }\n}\n\n\n\nfunction resetMinhHongState(){\n\n    minhHongState.studentCode=\"\";\n    minhHongState.studentName=\"\";\n    minhHongState.group=\"\";\n    minhHongState.course=\"\";\n    minhHongState.studentStatus=\"\";\n\n    minhHongState.identitySource=\"\";\n\n    minhHongState.priorityStudent=false;\n\n    minhHongState.selectedRoom=\"\";\n    minhHongState.assignedRoom=\"\";\n\n    minhHongState.verified=false;\n\n    minhHongState.correctRoom=false;\n    minhHongState.wrongRoom=false;\n\n    minhHongState.accessGranted=false;\n\n    minhHongState.roomLive=false;\n    minhHongState.meetReady=false;\n\n    minhHongState.lastReason=\"\";\n}\n\n\n\nfunction setMinhHongStudent(\n    student,\n    source\n){\n\n    student=\n        student || {};\n\n\n    minhHongState.studentName=\n        clean(\n            student.name\n        );\n\n\n    minhHongState.group=\n        clean(\n            student.group\n        );\n\n\n    minhHongState.course=\n        clean(\n            student.course\n        );\n\n\n    minhHongState.studentStatus=\n        clean(\n            student.status\n        );\n\n\n    minhHongState.identitySource=\n        clean(source);\n}\n\n\n\nfunction getRoomLiveState(room){\n\n    if(!room){\n\n        return false;\n    }\n\n\n    const badge=\n        el(\n            \"gdStatus\" +\n            room\n        );\n\n\n    return Boolean(\n        badge &&\n        badge.classList.contains(\n            \"live\"\n        )\n    );\n}\n\n\n\nfunction buildMinhHongContext(){\n\n    const selectedRoom=\n        minhHongState.selectedRoom;\n\n\n    const assignedRoom=\n        minhHongState.assignedRoom;\n\n\n    const selectedRoomName=\n        selectedRoom &&\n        CONFIG.rooms[selectedRoom]\n        ?\n        CONFIG.rooms[selectedRoom]\n        .displayName\n        :\n        \"\";\n\n\n    const assignedRoomName=\n        assignedRoom &&\n        CONFIG.rooms[assignedRoom]\n        ?\n        CONFIG.rooms[assignedRoom]\n        .displayName\n        :\n        \"\";\n\n\n    return{\n\n        page:\n            \"GiangDuong\",\n\n        studentCode:\n            minhHongState.studentCode,\n\n        data:{\n\n            studentName:\n                minhHongState.studentName,\n\n            group:\n                minhHongState.group,\n\n            course:\n                minhHongState.course,\n\n            studentStatus:\n                minhHongState.studentStatus,\n\n            identitySource:\n                minhHongState.identitySource,\n\n            priorityStudent:\n                minhHongState.priorityStudent,\n\n            selectedRoom:\n                selectedRoom,\n\n            selectedRoomName:\n                selectedRoomName,\n\n            assignedRoom:\n                assignedRoom,\n\n            assignedRoomName:\n                assignedRoomName,\n\n            roomLive:\n                minhHongState.roomLive,\n\n            meetReady:\n                minhHongState.meetReady,\n\n            accessGranted:\n                minhHongState.accessGranted,\n\n            lastReason:\n                minhHongState.lastReason\n\n        },\n\n\n        conditions:{\n\n            student_verified:\n                minhHongState.verified,\n\n            priority_student:\n                minhHongState.priorityStudent,\n\n            room_hoabinh:\n                assignedRoom ===\n                \"HOABINH\",\n\n            room_hanhphuc:\n                assignedRoom ===\n                \"HANHPHUC\",\n\n            selected_hoabinh:\n                selectedRoom ===\n                \"HOABINH\",\n\n            selected_hanhphuc:\n                selectedRoom ===\n                \"HANHPHUC\",\n\n            correct_room:\n                minhHongState.correctRoom,\n\n            wrong_room:\n                minhHongState.wrongRoom,\n\n            room_live:\n                minhHongState.roomLive,\n\n            room_closed:\n                minhHongState.verified &&\n                minhHongState.correctRoom &&\n                !minhHongState.roomLive,\n\n            meet_ready:\n                minhHongState.meetReady,\n\n            meet_missing:\n                minhHongState.verified &&\n                minhHongState.correctRoom &&\n                !minhHongState.meetReady,\n\n            access_granted:\n                minhHongState.accessGranted,\n\n            access_denied:\n                minhHongState.verified &&\n                !minhHongState.accessGranted,\n\n            legacy_student:\n                minhHongState.identitySource ===\n                \"XepHang\",\n\n            registry_student:\n                minhHongState.identitySource ===\n                \"HocVien\"\n\n        }\n\n    };\n}\n\n\n\nfunction syncMinhHongContext(){\n\n    if(\n        !minhHongState.studentCode ||\n        !minhHongState.verified\n    ){\n\n        return false;\n    }\n\n\n    const api=\n        getMinhHongContextAPI();\n\n\n    if(!api){\n\n        return false;\n    }\n\n\n    try{\n\n        api.set(\n            buildMinhHongContext(),\n            \"GiangDuong\"\n        );\n\n\n        return true;\n\n\n    }catch(error){\n\n        console.warn(\n            \"[Giang Duong Minh Hong Context]\",\n            error\n        );\n\n\n        return false;\n    }\n}\n\n\n\nfunction syncMinhHongContextLater(\n    attempt\n){\n\n    attempt=\n        Number(attempt || 0);\n\n\n    if(\n        syncMinhHongContext()\n    ){\n\n        return;\n    }\n\n\n    if(attempt >= 12){\n\n        return;\n    }\n\n\n    setTimeout(\n        function(){\n\n            syncMinhHongContextLater(\n                attempt + 1\n            );\n\n        },\n        250\n    );\n}\n\n\n\nfunction refreshMinhHongRoomState(){\n\n    if(\n        !minhHongState.verified ||\n        !minhHongState.selectedRoom\n    ){\n\n        return;\n    }\n\n\n    minhHongState.roomLive=\n        getRoomLiveState(\n            minhHongState.selectedRoom\n        );\n\n\n    const config=\n        getRoomConfig(\n            minhHongState.selectedRoom\n        );\n\n\n    minhHongState.meetReady=\n        Boolean(\n            config &&\n            clean(\n                config.meetUrl\n            )\n        );\n\n\n    if(\n        minhHongState.correctRoom\n    ){\n\n        minhHongState.lastReason=\n            minhHongState.roomLive\n            ?\n            \"room_live\"\n            :\n            \"room_closed\";\n    }\n\n\n    syncMinhHongContext();\n}\n\n\n\n/* =========================================================\n   UPDATE ROOM STATUS\n========================================================= */\n\nasync function updateRoomStatuses(){\n\n    const realStatus=\n        await loadRealMeetStatus();\n\n\n    const hoaBinhActive=\n\n        isRoomScheduledLive(\n            \"HOABINH\"\n        )\n\n        ||\n\n        Boolean(\n            realStatus &&\n            realStatus.HOABINH\n        );\n\n\n    const hanhPhucActive=\n\n        isRoomScheduledLive(\n            \"HANHPHUC\"\n        )\n\n        ||\n\n        Boolean(\n            realStatus &&\n            realStatus.HANHPHUC\n        );\n\n\n    setRoomStatus(\n        \"HOABINH\",\n        hoaBinhActive\n    );\n\n\n    setRoomStatus(\n        \"HANHPHUC\",\n        hanhPhucActive\n    );\n\n\n    const header=\n        el(\"gdHeaderStatus\");\n\n\n    const headerText=\n        el(\"gdHeaderStatusText\");\n\n\n    const anyActive=\n        hoaBinhActive ||\n        hanhPhucActive;\n\n\n    if(header){\n\n        header.classList.toggle(\n            \"live\",\n            anyActive\n        );\n    }\n\n\n    if(headerText){\n\n        if(\n            hoaBinhActive &&\n            hanhPhucActive\n        ){\n\n            headerText.textContent=\n                \"C\u1ea3 hai ph\u00f2ng h\u1ecdc \u0111ang ho\u1ea1t \u0111\u1ed9ng\";\n\n        }else if(hoaBinhActive){\n\n            headerText.textContent=\n                \"Ph\u00f2ng h\u1ecdc Ho\u00e0 B\u00ecnh \u0111ang ho\u1ea1t \u0111\u1ed9ng\";\n\n        }else if(hanhPhucActive){\n\n            headerText.textContent=\n                \"Ph\u00f2ng h\u1ecdc H\u1ea1nh Ph\u00fac \u0111ang ho\u1ea1t \u0111\u1ed9ng\";\n\n        }else{\n\n            headerText.textContent=\n\n                \"Ho\u00e0 B\u00ecnh: Th\u1ee9 S\u00e1u 19:00\"\n\n                +\n\n                CHAR.dash\n\n                +\n\n                \"21:00\"\n\n                +\n\n                \" \"\n\n                +\n\n                CHAR.bullet\n\n                +\n\n                \" H\u1ea1nh Ph\u00fac: Th\u1ee9 B\u1ea3y 19:00\"\n\n                +\n\n                CHAR.dash\n\n                +\n\n                \"21:00\";\n        }\n    }\n\n\n    refreshMinhHongRoomState();\n}\n\n\n\n/* =========================================================\n   ROOM CONFIG\n========================================================= */\n\nfunction getRoomConfig(room){\n\n    return{\n\n        room:room,\n\n        displayName:\n            CONFIG.rooms[\n                room\n            ].displayName,\n\n        meetUrl:\n            room === \"HOABINH\"\n            ?\n            CONFIG.hoaBinhMeetUrl\n            :\n            CONFIG.hanhPhucMeetUrl,\n\n        input:\n            el(\n                \"gdCode\" +\n                room\n            ),\n\n        button:\n            el(\n                \"gdVerify\" +\n                room\n            ),\n\n        message:\n            el(\n                \"gdMessage\" +\n                room\n            ),\n\n        access:\n            el(\n                \"gdMeetAccess\" +\n                room\n            )\n\n    };\n}\n\n\n\n/* =========================================================\n   MESSAGE\n========================================================= */\n\nfunction setRoomMessage(\n    config,\n    type,\n    text\n){\n\n    if(!config.message){\n\n        return;\n    }\n\n\n    config.message.className=\n        \"gd-room-message show \" +\n        type;\n\n\n    config.message.textContent=\n        text;\n}\n\n\n\nfunction clearRoom(config){\n\n    if(config.access){\n\n        config.access.classList.remove(\n            \"show\"\n        );\n\n\n        config.access.replaceChildren();\n    }\n\n\n    if(config.message){\n\n        config.message.className=\n            \"gd-room-message\";\n\n\n        config.message.textContent=\n            \"\";\n    }\n}\n\n\n\n/* =========================================================\n   MEET ACCESS\n========================================================= */\n\nfunction showMeetAccess(\n    config,\n    student\n){\n\n    if(!config.access){\n\n        return;\n    }\n\n\n    config.access.replaceChildren();\n\n\n    if(\n        !clean(\n            config.meetUrl\n        )\n    ){\n\n        setRoomMessage(\n            config,\n            \"warning\",\n            \"M\u00e3 h\u1ecdc vi\u00ean h\u1ee3p l\u1ec7. Gi\u00e1o vi\u00ean ch\u01b0a c\u00e0i link Google Meet cho ph\u00f2ng n\u00e0y.\"\n        );\n\n\n        return;\n    }\n\n\n    const link=\n        document.createElement(\n            \"a\"\n        );\n\n\n    link.className=\n        \"gd-meet-button\";\n\n\n    link.href=\n        config.meetUrl;\n\n\n    link.target=\n        \"_blank\";\n\n\n    link.rel=\n        \"noopener noreferrer\";\n\n\n    link.textContent=\n\n        ICON.video\n\n        +\n\n        \" V\u00c0O \"\n\n        +\n\n        config.displayName.toUpperCase();\n\n\n\n    const note=\n        document.createElement(\n            \"div\"\n        );\n\n\n    note.className=\n        \"gd-meet-small\";\n\n\n    if(\n        student &&\n        clean(student.name)\n    ){\n\n        note.textContent=\n            student.name +\n            \" - M\u00e3 h\u1ecdc vi\u00ean \u0111\u00e3 \u0111\u01b0\u1ee3c x\u00e1c minh.\";\n\n    }else{\n\n        note.textContent=\n            \"M\u00e3 h\u1ecdc vi\u00ean \u0111\u00e3 \u0111\u01b0\u1ee3c x\u00e1c minh.\";\n    }\n\n\n    config.access.appendChild(link);\n\n    config.access.appendChild(note);\n\n    config.access.classList.add(\n        \"show\"\n    );\n}\n\n\n\n/* =========================================================\n   VERIFY\n========================================================= */\n\nasync function verifyStudent(room){\n\n    const config=\n        getRoomConfig(room);\n\n\n    if(\n        !config.input ||\n        !config.button\n    ){\n\n        return;\n    }\n\n\n    const code=\n        normalizeCode(\n            config.input.value\n        );\n\n\n    config.input.value=\n        code;\n\n\n    clearRoom(config);\n\n\n    resetMinhHongState();\n\n\n    minhHongState.studentCode=\n        code;\n\n\n    minhHongState.selectedRoom=\n        room;\n\n\n    minhHongState.roomLive=\n        getRoomLiveState(room);\n\n\n    minhHongState.meetReady=\n        Boolean(\n            clean(\n                config.meetUrl\n            )\n        );\n\n\n    if(!code){\n\n        setRoomMessage(\n            config,\n            \"error\",\n            \"Vui l\u00f2ng nh\u1eadp M\u00e3 h\u1ecdc vi\u00ean.\"\n        );\n\n\n        config.input.focus();\n\n        return;\n    }\n\n\n    config.button.disabled=\n        true;\n\n\n    setRoomMessage(\n        config,\n        \"loading\",\n        \"\u0110ang x\u00e1c minh M\u00e3 h\u1ecdc vi\u00ean...\"\n    );\n\n\n    try{\n\n        /* =================================================\n           0. CENTRAL STUDENT STATUS GATE\n        ================================================= */\n\n        try{\n\n            const rewardSystem =\n                window.StudentRewardSystem;\n\n            if(\n                !rewardSystem ||\n                typeof rewardSystem.assertStudentActive !== \"function\"\n            ){\n\n                throw new Error(\n                    \"H\u1ec7 th\u1ed1ng tr\u1ea1ng th\u00e1i h\u1ecdc vi\u00ean ch\u01b0a s\u1eb5n s\u00e0ng.\"\n                );\n            }\n\n            await rewardSystem.assertStudentActive(\n                code,\n                {\n                    forceRefresh:true\n                }\n            );\n\n        }catch(accessError){\n\n            console.warn(\n                \"[Giang Duong Student Status Gate]\",\n                accessError\n            );\n\n            setRoomMessage(\n                config,\n                \"warning\",\n                clean(\n                    accessError &&\n                    accessError.message\n                )\n                ||\n                \"T\u00e0i kho\u1ea3n h\u1ecdc vi\u00ean \u0111ang t\u1ea1m d\u1eebng ho\u1eb7c ch\u01b0a \u0111\u01b0\u1ee3c k\u00edch ho\u1ea1t.\"\n            );\n\n            return;\n        }\n\n\n        /* =================================================\n           1. PRIORITY\n        ================================================= */\n\n        const priority=\n            await isPriorityStudent(\n                code\n            );\n\n\n        if(priority){\n\n            minhHongState.priorityStudent=\n                true;\n\n\n            minhHongState.verified=\n                true;\n\n\n            minhHongState.correctRoom=\n                true;\n\n\n            minhHongState.wrongRoom=\n                false;\n\n\n            minhHongState.assignedRoom=\n                room;\n\n\n            minhHongState.accessGranted=\n                true;\n\n\n            minhHongState.identitySource=\n                \"Priority\";\n\n\n            minhHongState.lastReason=\n                minhHongState.roomLive\n                ?\n                \"room_live\"\n                :\n                \"room_closed\";\n\n\n            confirmMinhHongStudent(\n                code\n            );\n\n\n            setRoomMessage(\n                config,\n                \"success\",\n                ICON.check +\n                \" X\u00e1c minh th\u00e0nh c\u00f4ng. B\u1ea1n c\u00f3 th\u1ec3 v\u00e0o ph\u00f2ng h\u1ecdc.\"\n            );\n\n\n            showMeetAccess(\n                config,\n                null\n            );\n\n\n            syncMinhHongContextLater(0);\n\n\n            return;\n        }\n\n\n\n        /* =================================================\n           2. HOCVIEN\n        ================================================= */\n\n        let registryStudent=null;\n\n\n        try{\n\n            const directory=\n                await loadDirectory();\n\n\n            registryStudent=\n                directory.get(code)\n                ||\n                null;\n\n\n        }catch(registryError){\n\n            console.error(\n                \"[Giang Duong HocVien]\",\n                registryError\n            );\n\n\n            setRoomMessage(\n                config,\n                \"error\",\n                \"Ch\u01b0a th\u1ec3 k\u1ebft n\u1ed1i danh s\u00e1ch h\u1ecdc vi\u00ean. Vui l\u00f2ng th\u1eed l\u1ea1i.\"\n            );\n\n\n            return;\n        }\n\n\n\n        let student=null;\n\n\n\n        if(registryStudent){\n\n            const accessStatus=\n                getStudentStatusMessage(\n                    registryStudent\n                );\n\n\n            if(\n                !accessStatus.allowed\n            ){\n\n                setRoomMessage(\n                    config,\n                    accessStatus.type,\n                    accessStatus.text\n                );\n\n\n                return;\n            }\n\n\n            student=\n                registryStudent;\n\n\n            setMinhHongStudent(\n                student,\n                \"HocVien\"\n            );\n\n\n        }else{\n\n            /* =============================================\n               CH\u1ec8 FALLBACK KHI HOCVIEN \u0110\u00c3 T\u1ea2I TH\u00c0NH C\u00d4NG\n               V\u00c0 KH\u00d4NG C\u00d3 M\u00c3\n            ============================================= */\n\n            let legacyDirectory;\n\n\n            try{\n\n                legacyDirectory=\n                    await loadLegacyDirectory();\n\n\n            }catch(legacyError){\n\n                console.error(\n                    \"[Giang Duong XepHang]\",\n                    legacyError\n                );\n\n\n                setRoomMessage(\n                    config,\n                    \"error\",\n                    \"Ch\u01b0a th\u1ec3 ki\u1ec3m tra d\u1eef li\u1ec7u h\u1ecdc vi\u00ean c\u0169. Vui l\u00f2ng th\u1eed l\u1ea1i.\"\n                );\n\n\n                return;\n            }\n\n\n            const legacyStudent=\n                legacyDirectory.get(code);\n\n\n            if(!legacyStudent){\n\n                setRoomMessage(\n                    config,\n                    \"error\",\n                    \"Kh\u00f4ng t\u00ecm th\u1ea5y M\u00e3 h\u1ecdc vi\u00ean n\u00e0y trong h\u1ec7 th\u1ed1ng.\"\n                );\n\n\n                return;\n            }\n\n\n            student=\n                legacyStudent;\n\n\n            setMinhHongStudent(\n                student,\n                \"XepHang\"\n            );\n        }\n\n\n\n        /* =================================================\n           \u0110\u1ecaNH DANH TH\u00c0NH C\u00d4NG\n        ================================================= */\n\n        minhHongState.verified=\n            true;\n\n\n        confirmMinhHongStudent(\n            code\n        );\n\n\n\n        /* =================================================\n           PH\u00c2N PH\u00d2NG\n        ================================================= */\n\n        const correctRoom=\n            roomForCode(code, room);\n\n\n        minhHongState.assignedRoom=\n            correctRoom;\n\n\n        if(!correctRoom){\n\n            minhHongState.correctRoom=\n                false;\n\n\n            minhHongState.wrongRoom=\n                false;\n\n\n            minhHongState.accessGranted=\n                false;\n\n\n            minhHongState.lastReason=\n                \"room_not_assigned\";\n\n\n            setRoomMessage(\n                config,\n                \"error\",\n                \"M\u00e3 h\u1ecdc vi\u00ean h\u1ee3p l\u1ec7 nh\u01b0ng ch\u01b0a \u0111\u01b0\u1ee3c ph\u00e2n quy\u1ec1n v\u00e0o hai ph\u00f2ng h\u1ecdc hi\u1ec7n t\u1ea1i.\"\n            );\n\n\n            syncMinhHongContextLater(0);\n\n\n            return;\n        }\n\n\n        if(\n            correctRoom !== room\n        ){\n\n            minhHongState.correctRoom=\n                false;\n\n\n            minhHongState.wrongRoom=\n                true;\n\n\n            minhHongState.accessGranted=\n                false;\n\n\n            minhHongState.lastReason=\n                \"wrong_room\";\n\n\n            setRoomMessage(\n                config,\n                \"warning\",\n\n                \"M\u00e3 h\u1ecdc vi\u00ean n\u00e0y thu\u1ed9c \" +\n\n                CONFIG.rooms[\n                    correctRoom\n                ].displayName +\n\n                \". Vui l\u00f2ng ch\u1ecdn \u0111\u00fang ph\u00f2ng h\u1ecdc.\"\n            );\n\n\n            syncMinhHongContextLater(0);\n\n\n            return;\n        }\n\n\n\n        /* =================================================\n           \u0110\u00daNG PH\u00d2NG\n        ================================================= */\n\n        minhHongState.correctRoom=\n            true;\n\n\n        minhHongState.wrongRoom=\n            false;\n\n\n        minhHongState.accessGranted=\n            true;\n\n\n        minhHongState.roomLive=\n            getRoomLiveState(\n                room\n            );\n\n\n        minhHongState.meetReady=\n            Boolean(\n                clean(\n                    config.meetUrl\n                )\n            );\n\n\n        minhHongState.lastReason=\n            minhHongState.roomLive\n            ?\n            \"room_live\"\n            :\n            \"room_closed\";\n\n\n        const studentName=\n            clean(\n                student &&\n                student.name\n            );\n\n\n        setRoomMessage(\n            config,\n            \"success\",\n\n            ICON.check +\n\n            \" X\u00e1c minh th\u00e0nh c\u00f4ng\" +\n\n            (\n                studentName\n                ?\n                \": \" +\n                studentName +\n                \".\"\n                :\n                \".\"\n            )\n\n            +\n\n            \" B\u1ea1n c\u00f3 th\u1ec3 v\u00e0o ph\u00f2ng h\u1ecdc.\"\n        );\n\n\n        showMeetAccess(\n            config,\n            student\n        );\n\n\n        syncMinhHongContextLater(0);\n\n\n    }catch(error){\n\n        console.error(\n            \"[Giang Duong v1.7.0 Verify]\",\n            error\n        );\n\n\n        setRoomMessage(\n            config,\n            \"error\",\n            \"Ch\u01b0a th\u1ec3 k\u1ebft n\u1ed1i d\u1eef li\u1ec7u h\u1ecdc vi\u00ean. Vui l\u00f2ng th\u1eed l\u1ea1i.\"\n        );\n\n\n    }finally{\n\n        config.button.disabled=\n            false;\n    }\n}\n\n\n\n/* =========================================================\n   STUDENT NAME FOR ACTIVITY\n========================================================= */\n\nfunction getStudentName(\n    code,\n    fallback\n){\n\n    fallback=\n        clean(fallback);\n\n\n    if(fallback){\n\n        return fallback;\n    }\n\n\n    code=\n        normalizeCode(code);\n\n\n    if(\n        state.directory &&\n        state.directory.has(code)\n    ){\n\n        const student=\n            state.directory.get(code);\n\n\n        if(\n            student &&\n            student.name\n        ){\n\n            return student.name;\n        }\n    }\n\n\n    if(\n        state.legacyDirectory &&\n        state.legacyDirectory.has(code)\n    ){\n\n        const student=\n            state.legacyDirectory.get(code);\n\n\n        if(\n            student &&\n            student.name\n        ){\n\n            return student.name;\n        }\n    }\n\n\n    return \"M\u1ed9t h\u1ecdc vi\u00ean\";\n}\n\n\n\n/* =========================================================\n   DATE\n========================================================= */\n\nfunction parseDate(value){\n\n    value=\n        clean(value);\n\n\n    if(!value){\n\n        return null;\n    }\n\n\n    let match=\n        value.match(\n            /^(\\d{1,2})[\\/\\-](\\d{1,2})[\\/\\-](\\d{4})[\\s,T]+(\\d{1,2}):(\\d{2})(?::(\\d{2}))?/\n        );\n\n\n    if(match){\n\n        const date=\n            new Date(\n\n                Number(match[3]),\n\n                Number(match[2])-1,\n\n                Number(match[1]),\n\n                Number(match[4]),\n\n                Number(match[5]),\n\n                Number(match[6] || 0)\n\n            );\n\n\n        if(\n            !Number.isNaN(\n                date.getTime()\n            )\n        ){\n\n            return date;\n        }\n    }\n\n\n    const nativeDate=\n        new Date(value);\n\n\n    return Number.isNaN(\n        nativeDate.getTime()\n    )\n    ?\n    null\n    :\n    nativeDate;\n}\n\n\n\nfunction relativeTime(date){\n\n    if(!date){\n\n        return \"G\u1ea7n \u0111\u00e2y\";\n    }\n\n\n    const diff=\n        Date.now() -\n        date.getTime();\n\n\n    const minute=\n        60000;\n\n    const hour=\n        minute * 60;\n\n    const day=\n        hour * 24;\n\n\n    if(diff < minute){\n\n        return \"V\u1eeba xong\";\n    }\n\n\n    if(diff < hour){\n\n        return(\n            Math.floor(\n                diff / minute\n            )\n            +\n            \" ph\u00fat tr\u01b0\u1edbc\"\n        );\n    }\n\n\n    if(diff < day){\n\n        return(\n            Math.floor(\n                diff / hour\n            )\n            +\n            \" gi\u1edd tr\u01b0\u1edbc\"\n        );\n    }\n\n\n    if(\n        diff <\n        day * 7\n    ){\n\n        return(\n            Math.floor(\n                diff / day\n            )\n            +\n            \" ng\u00e0y tr\u01b0\u1edbc\"\n        );\n    }\n\n\n    return date.toLocaleDateString(\n        \"vi-VN\"\n    );\n}\n\n\n\n/* =========================================================\n   SUBMISSION COLUMNS\n========================================================= */\n\nfunction detectSubmissionColumns(headers){\n\n    return{\n\n        time:\n            findColumn(\n                headers,\n                [\n                    \"D\u1ea5u th\u1eddi gian\",\n                    \"Timestamp\",\n                    \"Th\u1eddi gian n\u1ed9p\",\n                    \"Th\u1eddi gian\"\n                ]\n            ),\n\n        code:\n            findColumn(\n                headers,\n                [\n                    \"M\u00e3 h\u1ecdc vi\u00ean\",\n                    \"M\u00e3 HV\",\n                    \"S\u1ed1 b\u00e1o danh\",\n                    \"SBD\"\n                ]\n            ),\n\n        name:\n            findColumn(\n                headers,\n                [\n                    \"H\u1ecd v\u00e0 t\u00ean\",\n                    \"H\u1ecd t\u00ean\",\n                    \"T\u00ean h\u1ecdc vi\u00ean\"\n                ]\n            ),\n\n        score:\n            findColumn(\n                headers,\n                [\n                    \"\u0110i\u1ec3m s\u1ed1\",\n                    \"\u0110i\u1ec3m\"\n                ]\n            ),\n\n        comment:\n            findColumn(\n                headers,\n                [\n                    \"Nh\u1eadn x\u00e9t\",\n                    \"B\u00ecnh lu\u1eadn\"\n                ]\n            )\n\n    };\n}\n\n\n\n/* =========================================================\n   SUBMISSION ACTIVITIES\n========================================================= */\n\nfunction mapSubmissionActivities(rows){\n\n    const result=[];\n\n\n    if(\n        rows.length < 2\n    ){\n\n        return result;\n    }\n\n\n    const columns=\n        detectSubmissionColumns(\n            rows[0]\n        );\n\n\n    for(\n        let i=1;\n        i<rows.length;\n        i++\n    ){\n\n        const row=\n            rows[i];\n\n\n        const code=\n            columns.code >= 0\n            ?\n            clean(\n                row[columns.code]\n            )\n            :\n            \"\";\n\n\n        const rawName=\n            columns.name >= 0\n            ?\n            clean(\n                row[columns.name]\n            )\n            :\n            \"\";\n\n\n        if(\n            !code &&\n            !rawName\n        ){\n\n            continue;\n        }\n\n\n        const name=\n            getStudentName(\n                code,\n                rawName\n            );\n\n\n        const date=\n            columns.time >= 0\n            ?\n            parseDate(\n                row[columns.time]\n            )\n            :\n            null;\n\n\n        result.push({\n\n            type:\"submission\",\n\n            name:name,\n\n            date:date,\n\n            reliable:true\n\n        });\n\n\n        if(\n            columns.score >= 0 &&\n            clean(\n                row[columns.score]\n            )\n        ){\n\n            result.push({\n\n                type:\"grade\",\n\n                name:name,\n\n                date:date,\n\n                reliable:false\n\n            });\n        }\n\n\n        if(\n            columns.comment >= 0 &&\n            clean(\n                row[columns.comment]\n            )\n        ){\n\n            result.push({\n\n                type:\"comment\",\n\n                name:name,\n\n                date:date,\n\n                reliable:false\n\n            });\n        }\n\n    }\n\n\n    return result;\n}\n\n\n\n/* =========================================================\n   GIFT\n========================================================= */\n\nfunction giftCsvUrl(){\n\n    return(\n\n        \"https://docs.google.com/spreadsheets/d/\"\n\n        +\n\n        CONFIG.rewardSpreadsheetId\n\n        +\n\n        \"/gviz/tq?tqx=out:csv&sheet=\"\n\n        +\n\n        encodeURIComponent(\n            CONFIG.teacherGiftSheetName\n        )\n\n    );\n}\n\n\n\nfunction mapGiftActivities(rows){\n\n    const result=[];\n\n\n    if(\n        rows.length < 2\n    ){\n\n        return result;\n    }\n\n\n    const headers=\n        rows[0];\n\n\n    const timeColumn=\n        findColumn(\n            headers,\n            [\n                \"D\u1ea5u th\u1eddi gian\",\n                \"Timestamp\",\n                \"Th\u1eddi gian\",\n                \"Ng\u00e0y t\u1eb7ng\"\n            ]\n        );\n\n\n    const codeColumn=\n        findColumn(\n            headers,\n            [\n                \"M\u00e3 h\u1ecdc vi\u00ean\",\n                \"M\u00e3 HV\",\n                \"S\u1ed1 b\u00e1o danh\",\n                \"SBD\"\n            ]\n        );\n\n\n    const nameColumn=\n        findColumn(\n            headers,\n            [\n                \"H\u1ecd v\u00e0 t\u00ean\",\n                \"H\u1ecd t\u00ean\",\n                \"T\u00ean h\u1ecdc vi\u00ean\"\n            ]\n        );\n\n\n    for(\n        let i=1;\n        i<rows.length;\n        i++\n    ){\n\n        const row=\n            rows[i];\n\n\n        const code=\n            codeColumn >= 0\n            ?\n            clean(\n                row[codeColumn]\n            )\n            :\n            \"\";\n\n\n        const rawName=\n            nameColumn >= 0\n            ?\n            clean(\n                row[nameColumn]\n            )\n            :\n            \"\";\n\n\n        if(\n            !code &&\n            !rawName\n        ){\n\n            continue;\n        }\n\n\n        result.push({\n\n            type:\"gift\",\n\n            name:\n                getStudentName(\n                    code,\n                    rawName\n                ),\n\n            date:\n                timeColumn >= 0\n                ?\n                parseDate(\n                    row[timeColumn]\n                )\n                :\n                null,\n\n            reliable:\n                timeColumn >= 0\n\n        });\n\n    }\n\n\n    return result;\n}\n\n\n\n/* =========================================================\n   ACTIVITY INFO\n========================================================= */\n\nfunction activityInfo(type){\n\n    switch(type){\n\n        case \"submission\":\n\n            return{\n\n                icon:\n                    ICON.submission,\n\n                label:\n                    \"N\u1ed9p b\u00e0i\",\n\n                action:\n                    \"v\u1eeba t\u1ea3i l\u00ean m\u1ed9t b\u00e0i t\u1eadp m\u1edbi.\"\n\n            };\n\n\n        case \"grade\":\n\n            return{\n\n                icon:\n                    ICON.grade,\n\n                label:\n                    \"Ch\u1ea5m b\u00e0i\",\n\n                action:\n                    \"v\u1eeba \u0111\u01b0\u1ee3c gi\u00e1o vi\u00ean ho\u00e0n th\u00e0nh ch\u1ea5m b\u00e0i.\"\n\n            };\n\n\n        case \"comment\":\n\n            return{\n\n                icon:\n                    ICON.comment,\n\n                label:\n                    \"B\u00ecnh lu\u1eadn\",\n\n                action:\n                    \"v\u1eeba \u0111\u01b0\u1ee3c gi\u00e1o vi\u00ean b\u00ecnh lu\u1eadn b\u00e0i.\"\n\n            };\n\n\n        case \"gift\":\n\n            return{\n\n                icon:\n                    ICON.gift,\n\n                label:\n                    \"T\u1eb7ng qu\u00e0\",\n\n                action:\n                    \"v\u1eeba nh\u1eadn \u0111\u01b0\u1ee3c m\u1ed9t ph\u1ea7n qu\u00e0.\"\n\n            };\n\n    }\n\n\n    return{\n\n        icon:\n            ICON.book,\n\n        label:\n            \"Ho\u1ea1t \u0111\u1ed9ng\",\n\n        action:\n            \"v\u1eeba c\u00f3 ho\u1ea1t \u0111\u1ed9ng m\u1edbi.\"\n\n    };\n}\n\n\n\n/* =========================================================\n   ACTIVITY NODE\n========================================================= */\n\nfunction buildActivityNode(activity){\n\n    const card=\n        document.createElement(\"article\");\n\n    card.className=\n        \"gd-lammo-card\";\n\n    const photo=\n        document.createElement(\"button\");\n\n    photo.type=\n        \"button\";\n\n    photo.className=\n        \"gd-lammo-photo\";\n\n    photo.setAttribute(\n        \"aria-label\",\n        \"Xem l\u1edbn b\u1ea3n l\u00e2m c\u1ee7a \" + activity.name\n    );\n\n    if(activity.photo){\n\n        const img=\n            document.createElement(\"img\");\n\n        img.loading=\n            \"lazy\";\n\n        img.decoding=\n            \"async\";\n\n        img.alt=\n            \"B\u1ea3n l\u00e2m c\u1ee7a \" + activity.name;\n\n        img.src=\n            lamMoImageUrl(activity.photo,600);\n\n        img.addEventListener(\n            \"error\",\n            function(){\n                if(!img.dataset.retry){\n                    img.dataset.retry=\"1\";\n                    img.src=\n                        lamMoImageUrl(activity.photo,600,true);\n                }else{\n                    img.remove();\n                    photo.classList.add(\"is-error\");\n                }\n            }\n        );\n\n        photo.appendChild(img);\n\n    }else{\n\n        photo.classList.add(\"is-error\");\n    }\n\n    photo.addEventListener(\n        \"click\",\n        function(){\n            openLamMoViewer(activity);\n        }\n    );\n\n    const heart=\n        document.createElement(\"button\");\n\n    heart.type=\n        \"button\";\n\n    heart.className=\n        \"gd-lammo-heart\";\n\n    paintLamMoHeart(\n        heart,\n        activity.liked,\n        activity.hearts\n    );\n\n    heart.addEventListener(\n        \"click\",\n        function(){\n            toggleLamMoHeart(\n                activity,\n                heart\n            );\n        }\n    );\n\n    const info=\n        document.createElement(\"div\");\n\n    info.className=\n        \"gd-lammo-info\";\n\n    const name=\n        document.createElement(\"div\");\n\n    name.className=\n        \"gd-lammo-name\";\n\n    name.textContent=\n        activity.name;\n\n    name.title=\n        activity.name;\n\n    const sub=\n        document.createElement(\"div\");\n\n    sub.className=\n        \"gd-lammo-sub\";\n\n    sub.textContent=\n        [\n            activity.group ? \"T\u1ed5 \" + activity.group : \"\",\n            activity.course ? \"Kh\u00f3a \" + activity.course : \"\"\n        ]\n        .filter(Boolean)\n        .join(\" \" + String.fromCharCode(183) + \" \")\n        ||\n        \"H\u1ecdc vi\u00ean\";\n\n    /* v1.9.1: b\u1ea5m t\u00ean b\u1ea3n l\u00e2m -> m\u1edf \u0111\u00fang b\u1ea3n m\u1eabu tr\u00ean trang Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4 */\n    const title=\n        document.createElement(activity.lessonId ? \"a\" : \"div\");\n\n    title.className=\n        \"gd-lammo-title\";\n\n    if(activity.lessonId){\n\n        title.href=\n            LAMMO.page + \"?lm=\" + encodeURIComponent(activity.lessonId);\n\n        title.title=\n            \"Xem b\u1ea3n m\u1eabu tr\u00ean Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4\";\n    }\n\n    title.textContent=\n        String.fromCharCode(8220) + (activity.title || \"L\u00e2m m\u00f4\") + String.fromCharCode(8221);\n\n    const time=\n        document.createElement(\"div\");\n\n    time.className=\n        \"gd-lammo-time\";\n\n    time.textContent=\n        \"G\u00f3p \" +\n        (\n            activity.reliable\n            ?\n            relativeTime(activity.date)\n            :\n            \"g\u1ea7n \u0111\u00e2y\"\n        );\n\n    info.appendChild(name);\n    info.appendChild(sub);\n    info.appendChild(title);\n    info.appendChild(time);\n\n    card.appendChild(photo);\n    card.appendChild(heart);\n    card.appendChild(info);\n\n    return card;\n}\n\n\n\n/* =========================================================\n   FILTER\n========================================================= */\n\nfunction filteredActivities(){\n\n    if(\n        state.activityFilter ===\n        \"all\"\n    ){\n\n        return state.activities;\n    }\n\n\n    return state.activities.filter(\n        function(item){\n\n            return(\n                item.type ===\n                state.activityFilter\n            );\n        }\n    );\n}\n\n\n\n/* =========================================================\n   RENDER ACTIVITIES\n========================================================= */\n\nfunction renderActivities(){\n\n    const feed=\n        el(\"gdActivityFeed\");\n\n\n    const wrap=\n        el(\"gdLoadMoreWrap\");\n\n\n    if(\n        !feed ||\n        !wrap\n    ){\n\n        return;\n    }\n\n\n    const activities=\n        filteredActivities();\n\n\n    feed.replaceChildren();\n\n\n    if(!activities.length){\n\n        const empty=\n            document.createElement(\n                \"div\"\n            );\n\n\n        empty.className=\n            \"gd-empty\";\n\n\n        empty.textContent=\n            \"Ch\u01b0a c\u00f3 ho\u1ea1t \u0111\u1ed9ng \u0111\u1ec3 hi\u1ec3n th\u1ecb.\";\n\n\n        feed.appendChild(empty);\n\n\n        wrap.classList.remove(\n            \"show\"\n        );\n\n\n        return;\n    }\n\n\n    const limit=\n        Math.min(\n            state.visibleActivityCount,\n            activities.length\n        );\n\n\n    const fragment=\n        document.createDocumentFragment();\n\n\n    for(\n        let i=0;\n        i<limit;\n        i++\n    ){\n\n        fragment.appendChild(\n            buildActivityNode(\n                activities[i]\n            )\n        );\n    }\n\n\n    feed.appendChild(fragment);\n\n\n    wrap.classList.toggle(\n        \"show\",\n        limit <\n        activities.length\n    );\n}\n\n\n\n/* =========================================================\n   LOAD ACTIVITY\n========================================================= */\n\n/* v1.9.0: NH\u1ecaP S\u1ed0NG L\u1edaP H\u1eccC = b\u1ea3n l\u00e2m h\u1ecdc vi\u00ean v\u1eeba \u0111\u00f3ng g\u00f3p v\u00e0o Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4 (\u1ea3nh l\u1edbn + th\u1ea3 tim).\n   \u0110\u1ecdc th\u1eb3ng Sheet \"T\u1ea1o b\u00e0i l\u00e2m m\u00f4\": BanLamHocVien (ch\u1ec9 TrangThai \"Hi\u1ec3n th\u1ecb\")\n   + TimBanLam (\u0111\u1ebfm tim gi\u1ed1ng trang Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4). Kh\u00f4ng t\u1ea3i HocVien / b\u00e0i n\u1ed9p n\u1eefa -> trang nh\u1eb9 h\u01a1n. */\nconst LAMMO={\n\n    sheet:\n        \"1MmqY19BSi8L6xdsF5cg1qZssrERSrqBH6nEGZjqOMLI\",\n\n    banGid:\n        176543211,\n\n    timGid:\n        176543212,\n\n    page:\n        \"https://www.thudao.com/p/thu-vien-lam-mo.html\",\n\n    /* Apps Script c\u1ee7a trang Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4: th\u1ea3 tim + heartState (s\u1ed1 tim hai trang lu\u00f4n gi\u1ed1ng nhau) */\n    api:\n        \"https://script.google.com/macros/s/AKfycbz4pa-q_ALScuiY8tbhi5bdJ0MPtl-IBu6gjZuDeFXuailbvPYhlk1TmE_Hq4DjJxHFIg/exec\",\n\n    firstPage:\n        8\n};\n\nconst lamMoHeartPending=\n    new Set();\n\n\nfunction lamMoImageUrl(id,size,fallback){\n\n    return(\n        fallback\n        ?\n        \"https://lh3.googleusercontent.com/d/\" + encodeURIComponent(id) + \"=w\" + size\n        :\n        \"https://drive.google.com/thumbnail?id=\" + encodeURIComponent(id) + \"&sz=w\" + size\n    );\n}\n\n\n/* Sheet c\u00f3 th\u1ec3 m\u1ea5t s\u1ed1 0 \u0111\u1ea7u (050303 -> 50303) */\nfunction lamMoWho(code){\n\n    return normalizeCode(code).replace(/^0+(?=\\d)/,\"\");\n}\n\n\nfunction lamMoCsvUrl(gid){\n\n    return(\n        \"https://docs.google.com/spreadsheets/d/\" +\n        LAMMO.sheet +\n        \"/export?format=csv&gid=\" +\n        gid +\n        \"&_=\" +\n        Math.floor(Date.now() / 60000)\n    );\n}\n\n\nfunction lamMoObjects(text){\n\n    if(/^\\s*</.test(String(text || \"\"))){\n\n        throw new Error(\n            \"Kh\u00f4ng \u0111\u1ecdc \u0111\u01b0\u1ee3c d\u1eef li\u1ec7u Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4.\"\n        );\n    }\n\n    const rows=\n        parseCSV(text);\n\n    const head=\n        (rows[0] || []).map(\n            function(h){\n                return clean(h).toLowerCase().replace(/\\s+/g,\"\");\n            }\n        );\n\n    return rows.slice(1).map(\n        function(r){\n            const o={};\n            head.forEach(\n                function(k,i){\n                    if(k){\n                        o[k]=clean(r[i]);\n                    }\n                }\n            );\n            return o;\n        }\n    );\n}\n\n\n/* M\u1ed7i MaTim l\u1ea5y tr\u1ea1ng th\u00e1i m\u1edbi nh\u1ea5t, \u0111\u1ebfm DangThaTim = TRUE theo MaKhoe */\nfunction lamMoHeartCounts(tim){\n\n    const last={};\n\n    tim.forEach(\n        function(r){\n            const who=\n                lamMoWho(r.mahocvien);\n            const id=\n                r.matim ||\n                (r.makhoe + \"|\" + who);\n            last[id]={\n                key:r.makhoe,\n                who:who,\n                on:/^(true|1|x|yes|co|c\u00f3)$/i.test(clean(r.dangthatim))\n            };\n        }\n    );\n\n    const count={},\n        mine={};\n\n    Object.keys(last).forEach(\n        function(id){\n            const x=last[id];\n            if(x.on && x.key){\n                count[x.key]=(count[x.key] || 0) + 1;\n                mine[x.key + \"|\" + x.who]=true;\n            }\n        }\n    );\n\n    return{\n        count:count,\n        mine:mine\n    };\n}\n\n\nfunction lamMoDriveId(value){\n\n    value=clean(value);\n\n    const m=\n        value.match(/[-\\w]{25,}/);\n\n    return m ? m[0] : \"\";\n}\n\n\nfunction mapLamMoActivities(ban,tim){\n\n    const hearts=\n        lamMoHeartCounts(tim);\n\n    const viewer=\n        lamMoWho(sessionStudentCode());\n\n    state.lamMoViewer=\n        viewer;\n\n    return ban\n    .filter(\n        function(r){\n            return(\n                r.makhoe &&\n                /hien\\s*thi|hi\u1ec3n\\s*th\u1ecb/i.test(r.trangthai || \"\")\n            );\n        }\n    )\n    .map(\n        function(r){\n            const date=\n                parseDate(r.ngaykhoe);\n            const photo=\n                lamMoDriveId(r.fileanh) ||\n                lamMoDriveId(r.linkbainop);\n            return{\n                type:\"lammo\",\n                id:r.makhoe,\n                lessonId:r.mabailammo || \"\",\n                studentCode:r.mahocvien || \"\",\n                name:r.hoten || \"H\u1ecdc vi\u00ean\",\n                group:r.to || \"\",\n                course:r.khoa || \"\",\n                title:r.noidungmau || \"\",\n                hearts:hearts.count[r.makhoe] || 0,\n                liked:Boolean(\n                    viewer &&\n                    hearts.mine[r.makhoe + \"|\" + viewer]\n                ),\n                photo:photo,\n                link:\n                    photo\n                    ?\n                    \"https://drive.google.com/file/d/\" + photo + \"/view\"\n                    :\n                    LAMMO.page,\n                date:date,\n                reliable:Boolean(date)\n            };\n        }\n    );\n}\n\n\nasync function loadActivities(){\n\n    /* \u0111ang th\u1ea3 tim -> ch\u1edd xong m\u1edbi l\u00e0m m\u1edbi, tr\u00e1nh v\u1ebd l\u1ea1i gi\u1eefa ch\u1eebng */\n    if(\n        state.loadingActivity ||\n        lamMoHeartPending.size\n    ){\n\n        return;\n    }\n\n    state.loadingActivity=\n        true;\n\n    try{\n\n        const results=\n            await Promise.allSettled([\n                fetchText(lamMoCsvUrl(LAMMO.banGid)),\n                fetchText(lamMoCsvUrl(LAMMO.timGid))\n            ]);\n\n        if(results[0].status !== \"fulfilled\"){\n\n            throw results[0].reason;\n        }\n\n        const ban=\n            lamMoObjects(results[0].value);\n\n        let tim=[];\n\n        if(results[1].status === \"fulfilled\"){\n\n            try{\n                tim=lamMoObjects(results[1].value);\n            }catch(timError){\n                console.warn(\n                    \"[Giang Duong Lam Mo Hearts]\",\n                    timError\n                );\n            }\n        }\n\n        const activities=\n            mapLamMoActivities(ban,tim);\n\n        activities.sort(\n            function(a,b){\n                return(\n                    (b.date ? b.date.getTime() : 0) -\n                    (a.date ? a.date.getTime() : 0)\n                );\n            }\n        );\n\n        state.activityFilter=\n            \"all\";\n\n        state.activities=\n            activities.slice(\n                0,\n                CONFIG.maxActivities\n            );\n\n        state.visibleActivityCount=\n            Math.max(\n                LAMMO.firstPage,\n                state.lamMoShown || 0\n            );\n\n        state.lamMoShown=\n            state.visibleActivityCount;\n\n        renderActivities();\n\n        const feed=\n            el(\"gdActivityFeed\");\n\n        if(\n            feed &&\n            !state.activities.length\n        ){\n\n            const empty=\n                feed.querySelector(\".gd-empty\");\n\n            if(empty){\n\n                empty.textContent=\n                    \"Ch\u01b0a c\u00f3 b\u1ea3n l\u00e2m n\u00e0o. H\u00e3y l\u00e0 ng\u01b0\u1eddi \u0111\u1ea7u ti\u00ean \u0111\u00f3ng g\u00f3p cho Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4!\";\n            }\n        }\n\n    }catch(error){\n\n        console.error(\n            \"[Giang Duong Lam Mo]\",\n            error\n        );\n\n        const feed=\n            el(\"gdActivityFeed\");\n\n        if(feed){\n\n            feed.replaceChildren();\n\n            const empty=\n                document.createElement(\"div\");\n\n            empty.className=\n                \"gd-empty\";\n\n            empty.textContent=\n                \"Ch\u01b0a th\u1ec3 t\u1ea3i b\u1ea3n l\u00e2m m\u1edbi \u0111\u00f3ng g\u00f3p. B\u1ea5m n\u00fat M\u1edbi \u0111\u1ec3 th\u1eed l\u1ea1i.\";\n\n            feed.appendChild(empty);\n        }\n\n    }finally{\n\n        state.loadingActivity=\n            false;\n    }\n}\n\n\n\n/* =========================================================\n   v1.9.0 - TH\u1ea2 TIM + XEM \u1ea2NH L\u1edaN\n========================================================= */\n\nfunction paintLamMoHeart(button,liked,count){\n\n    button.classList.toggle(\n        \"is-liked\",\n        Boolean(liked)\n    );\n\n    button.setAttribute(\n        \"aria-pressed\",\n        String(Boolean(liked))\n    );\n\n    button.setAttribute(\n        \"aria-label\",\n        liked ? \"B\u1ecf tim\" : \"Th\u1ea3 tim\"\n    );\n\n    button.replaceChildren();\n\n    const icon=\n        document.createElement(\"span\");\n\n    icon.textContent=\n        String.fromCharCode(liked ? 9829 : 9825);\n\n    button.appendChild(icon);\n\n    button.appendChild(\n        document.createTextNode(\n            String(Math.max(0,Number(count) || 0))\n        )\n    );\n}\n\n\nfunction lamMoStatus(text){\n\n    const box=\n        el(\"gdLamMoStatus\");\n\n    if(!box){\n        return;\n    }\n\n    box.textContent=\n        text || \"\";\n\n    box.classList.toggle(\n        \"show\",\n        Boolean(text)\n    );\n}\n\n\nfunction readLamMoHeartState(post,code){\n\n    return new Promise(\n        function(resolve,reject){\n\n            const cb=\n                \"LMVideo_GDHeart_\" + Math.random().toString(36).slice(2);\n\n            const script=\n                document.createElement(\"script\");\n\n            let timer=null;\n\n            const cleanup=\n                function(){\n                    clearTimeout(timer);\n                    script.remove();\n                    try{\n                        delete window[cb];\n                    }catch(error){\n                        window[cb]=undefined;\n                    }\n                };\n\n            window[cb]=\n                function(result){\n                    cleanup();\n                    if(result && result.ok){\n                        resolve(result);\n                    }else{\n                        reject(new Error((result && result.message) || \"Kh\u00f4ng \u0111\u1ecdc \u0111\u01b0\u1ee3c tr\u1ea1ng th\u00e1i tim.\"));\n                    }\n                };\n\n            script.onerror=\n                function(){\n                    cleanup();\n                    reject(new Error(\"M\u1ea5t k\u1ebft n\u1ed1i Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4.\"));\n                };\n\n            timer=\n                setTimeout(\n                    function(){\n                        cleanup();\n                        reject(new Error(\"Th\u01b0 vi\u1ec7n l\u00e2m m\u00f4 ph\u1ea3n h\u1ed3i ch\u1eadm.\"));\n                    },\n                    8000\n                );\n\n            script.src=\n                LAMMO.api +\n                \"?action=heartState\" +\n                \"&lessonId=\" + encodeURIComponent(post.lessonId) +\n                \"&code=\" + encodeURIComponent(code) +\n                \"&postId=\" + encodeURIComponent(post.id) +\n                \"&callback=\" + cb;\n\n            document.head.appendChild(script);\n        }\n    );\n}\n\n\nasync function toggleLamMoHeart(post,button){\n\n    if(\n        !post ||\n        !post.id ||\n        lamMoHeartPending.has(post.id)\n    ){\n        return;\n    }\n\n    const code=\n        sessionStudentCode();\n\n    if(!code){\n\n        alert(\"H\u00e3y \u0111\u0103ng nh\u1eadp (bi\u1ec3u t\u01b0\u1ee3ng Minh H\u1ed3ng) \u0111\u1ec3 th\u1ea3 tim cho b\u1ea3n l\u00e2m.\");\n        return;\n    }\n\n    if(!post.lessonId){\n\n        alert(\"B\u1ea3n l\u00e2m n\u00e0y ch\u01b0a g\u1eafn b\u00e0i m\u1eabu n\u00ean ch\u01b0a th\u1ea3 tim \u0111\u01b0\u1ee3c.\");\n        return;\n    }\n\n    if(lamMoWho(post.studentCode) === lamMoWho(code)){\n\n        alert(\"Kh\u00f4ng th\u1ec3 th\u1ea3 tim b\u1ea3n l\u00e2m c\u1ee7a ch\u00ednh m\u00ecnh.\");\n        return;\n    }\n\n    const active=\n        !post.liked;\n\n    const oldCount=\n        Number(post.hearts) || 0;\n\n    lamMoHeartPending.add(post.id);\n\n    lamMoStatus(\"\");\n\n    button.disabled=\n        true;\n\n    paintLamMoHeart(\n        button,\n        active,\n        oldCount + (active ? 1 : -1)\n    );\n\n    const frame=\n        document.createElement(\"iframe\");\n\n    const form=\n        document.createElement(\"form\");\n\n    frame.name=\n        \"gdHeart_\" + Math.random().toString(36).slice(2);\n\n    frame.hidden=\n        true;\n\n    frame.title=\n        \"\u0110\u1ed3ng b\u1ed9 tim\";\n\n    form.hidden=\n        true;\n\n    form.method=\n        \"POST\";\n\n    form.action=\n        LAMMO.api;\n\n    form.target=\n        frame.name;\n\n    const fields={\n        action:\"heart\",\n        studentCode:code,\n        lessonId:post.lessonId,\n        postId:post.id,\n        active:String(active)\n    };\n\n    Object.keys(fields).forEach(\n        function(key){\n            const input=\n                document.createElement(\"input\");\n            input.type=\"hidden\";\n            input.name=key;\n            input.value=fields[key];\n            form.appendChild(input);\n        }\n    );\n\n    document.body.appendChild(frame);\n    document.body.appendChild(form);\n\n    try{\n\n        form.submit();\n\n        let confirmed=null,\n            lastError=\"\";\n\n        for(let attempt=0;attempt<8;attempt++){\n\n            await new Promise(\n                function(resolve){\n                    setTimeout(resolve,1500);\n                }\n            );\n\n            try{\n                const result=\n                    await readLamMoHeartState(post,code);\n                if(result.active === active){\n                    confirmed=result;\n                    break;\n                }\n            }catch(error){\n                lastError=error.message;\n            }\n        }\n\n        if(!confirmed){\n\n            throw new Error(\n                lastError ||\n                \"Ch\u01b0a x\u00e1c nh\u1eadn \u0111\u01b0\u1ee3c tim. H\u00e3y b\u1ea5m M\u1edbi \u0111\u1ec3 ki\u1ec3m tra l\u1ea1i.\"\n            );\n        }\n\n        post.liked=\n            Boolean(confirmed.active);\n\n        post.hearts=\n            Number(confirmed.hearts);\n\n        if(!Number.isFinite(post.hearts)){\n\n            post.hearts=\n                Math.max(0,oldCount + (active ? 1 : -1));\n        }\n\n    }catch(error){\n\n        lamMoStatus(error.message);\n\n    }finally{\n\n        paintLamMoHeart(\n            button,\n            post.liked,\n            post.hearts\n        );\n\n        lamMoHeartPending.delete(post.id);\n\n        button.disabled=\n            false;\n\n        form.remove();\n        frame.remove();\n    }\n}\n\n\nfunction closeLamMoViewer(){\n\n    const box=\n        el(\"gdLamMoViewer\");\n\n    if(!box){\n        return;\n    }\n\n    box.classList.remove(\"show\");\n\n    const img=\n        box.querySelector(\"img\");\n\n    if(img){\n        img.removeAttribute(\"src\");\n    }\n\n    document.documentElement.style.overflow=\n        state.lamMoOverflow || \"\";\n}\n\n\nfunction openLamMoViewer(post){\n\n    if(!post || !post.photo){\n        return;\n    }\n\n    let box=\n        el(\"gdLamMoViewer\");\n\n    if(!box){\n\n        box=\n            document.createElement(\"div\");\n\n        box.id=\n            \"gdLamMoViewer\";\n\n        box.className=\n            \"gd-lammo-viewer\";\n\n        box.setAttribute(\"role\",\"dialog\");\n        box.setAttribute(\"aria-modal\",\"true\");\n\n        const close=\n            document.createElement(\"button\");\n\n        close.type=\n            \"button\";\n\n        close.className=\n            \"gd-lammo-close\";\n\n        close.setAttribute(\"aria-label\",\"\u0110\u00f3ng\");\n\n        close.textContent=\n            String.fromCharCode(215);\n\n        close.addEventListener(\"click\",closeLamMoViewer);\n\n        const figure=\n            document.createElement(\"figure\");\n\n        const img=\n            document.createElement(\"img\");\n\n        img.alt=\n            \"B\u1ea3n l\u00e2m\";\n\n        img.addEventListener(\n            \"error\",\n            function(){\n                if(img.dataset.photo && !img.dataset.retry){\n                    img.dataset.retry=\"1\";\n                    img.src=lamMoImageUrl(img.dataset.photo,1600,true);\n                }\n            }\n        );\n\n        const caption=\n            document.createElement(\"figcaption\");\n\n        figure.appendChild(img);\n        figure.appendChild(caption);\n\n        box.appendChild(close);\n        box.appendChild(figure);\n\n        box.addEventListener(\n            \"click\",\n            function(event){\n                if(event.target === box){\n                    closeLamMoViewer();\n                }\n            }\n        );\n\n        document.addEventListener(\n            \"keydown\",\n            function(event){\n                if(event.key === \"Escape\"){\n                    closeLamMoViewer();\n                }\n            }\n        );\n\n        /* \u0111\u1eb7t trong #lectureHallPage \u0111\u1ec3 nh\u1eadn CSS c\u1ee7a trang */\n        (el(\"lectureHallPage\") || document.body).appendChild(box);\n    }\n\n    const img=\n        box.querySelector(\"img\");\n\n    img.dataset.photo=\n        post.photo;\n\n    img.dataset.retry=\n        \"\";\n\n    img.src=\n        lamMoImageUrl(post.photo,1600);\n\n    img.alt=\n        \"B\u1ea3n l\u00e2m c\u1ee7a \" + post.name;\n\n    box.querySelector(\"figcaption\").textContent=\n        post.name +\n        \" \" + String.fromCharCode(183) + \" \" + String.fromCharCode(8220) + (post.title || \"L\u00e2m m\u00f4\") + String.fromCharCode(8221) +\n        \" \" + String.fromCharCode(183) + \" \" + String.fromCharCode(9829) + \" \" + (Number(post.hearts) || 0);\n\n    state.lamMoOverflow=\n        document.documentElement.style.overflow;\n\n    document.documentElement.style.overflow=\n        \"hidden\";\n\n    box.classList.add(\"show\");\n}\n\n\n\n/* =========================================================\n   v1.8.0 - T\u1ef0 NH\u1eacN DI\u1ec6N H\u1eccC VI\u00caN (Minh H\u1ed3ng / t\u00e0i kho\u1ea3n)\n   C\u00f3 m\u00e3 -> t\u1ef1 ki\u1ec3m tra nh\u01b0 b\u1ea5m KI\u1ec2M TRA \u1edf m\u1ecdi ph\u00f2ng h\u1ecdc vi\u00ean\n   \u0111\u01b0\u1ee3c ph\u00e2n v\u00e0o (m\u00e3 \u01b0u ti\u00ean: c\u1ea3 hai ph\u00f2ng). \u0110\u1ee7 \u0111i\u1ec1u ki\u1ec7n -> m\u1edf ph\u00f2ng.\n========================================================= */\n\nconst autoState={\n    code:\"\",\n    running:false\n};\n\n\nfunction isMemberCode(code){\n\n    return(\n        /^TV\\d{6}$/.test(code) &&\n        !/^TV(?!00)\\d{2,3}0[1-4]01$/.test(code)\n    );\n}\n\n\nfunction sessionStudentCode(){\n\n    try{\n\n        const session=\n            window.OCDStudentSession;\n\n        const current=\n            session &&\n            typeof session.getState === \"function\"\n            ?\n            session.getState()\n            :\n            null;\n\n        if(\n            current &&\n            current.mode === \"student\" &&\n            current.code\n        ){\n\n            const code=\n                normalizeCode(current.code);\n\n            if(\n                code &&\n                code !== \"ADMIN\" &&\n                !isMemberCode(code)\n            ){\n                return code;\n            }\n        }\n\n    }catch(error){}\n\n    try{\n\n        const A=\n            window.OCDAuth;\n\n        const me=\n            A &&\n            typeof A.token === \"function\" &&\n            A.token() &&\n            typeof A.me === \"function\"\n            ?\n            A.me()\n            :\n            null;\n\n        if(me){\n\n            const code=\n                normalizeCode(\n                    me.linked ||\n                    (me.type !== \"TV\" ? me.code : \"\") ||\n                    \"\"\n                );\n\n            if(\n                code &&\n                !isMemberCode(code)\n            ){\n                return code;\n            }\n        }\n\n    }catch(error){}\n\n    return \"\";\n}\n\n\nasync function autoVerifySession(){\n\n    const code=\n        sessionStudentCode();\n\n    if(\n        !code ||\n        autoState.running ||\n        code === autoState.code\n    ){\n        return;\n    }\n\n    if(window.StudentRewardSystemReady){\n\n        try{\n            await window.StudentRewardSystemReady;\n        }catch(error){}\n    }\n\n    const rewardSystem=\n        window.StudentRewardSystem;\n\n    if(\n        !rewardSystem ||\n        typeof rewardSystem.assertStudentActive !== \"function\"\n    ){\n        /* h\u1ec7 th\u1ed1ng tr\u1ea1ng th\u00e1i ch\u01b0a s\u1eb5n s\u00e0ng -> l\u1ea7n th\u1eed sau */\n        return;\n    }\n\n    autoState.running=\n        true;\n\n    autoState.code=\n        code;\n\n    /* bi\u1ebft m\u00e3 h\u1ecdc vi\u00ean -> v\u1ebd l\u1ea1i tr\u00e1i tim \u0111\u00e3 th\u1ea3 c\u1ee7a ch\u00ednh h\u1ecdc vi\u00ean */\n    if(state.lamMoViewer !== lamMoWho(code)){\n        loadActivities();\n    }\n\n    try{\n\n        let priority=\n            false;\n\n        try{\n            priority=\n                await isPriorityStudent(code);\n        }catch(error){}\n\n        let rooms=\n            [\"HOABINH\",\"HANHPHUC\"].filter(\n                function(room){\n                    return(\n                        priority ||\n                        roomForCode(code,room) === room\n                    );\n                }\n            );\n\n        if(!rooms.length){\n\n            rooms=[\"HOABINH\"];\n        }\n\n        /* ph\u00f2ng \u0111ang h\u1ecdc h\u00f4m nay ki\u1ec3m tra sau c\u00f9ng -> Minh H\u1ed3ng theo ph\u00f2ng \u0111\u00f3 */\n        rooms.sort(\n            function(a,b){\n                return(\n                    (getRoomLiveState(a) ? 1 : 0) -\n                    (getRoomLiveState(b) ? 1 : 0)\n                );\n            }\n        );\n\n        [\"HOABINH\",\"HANHPHUC\"].forEach(\n            function(room){\n                const config=\n                    getRoomConfig(room);\n                if(\n                    config.input &&\n                    !clean(config.input.value)\n                ){\n                    config.input.value=code;\n                }\n            }\n        );\n\n        for(const room of rooms){\n\n            const config=\n                getRoomConfig(room);\n\n            if(config.input){\n\n                config.input.value=\n                    code;\n            }\n\n            await verifyStudent(room);\n        }\n\n    }catch(error){\n\n        console.warn(\n            \"[Giang Duong Auto Verify]\",\n            error\n        );\n\n        autoState.code=\"\";\n\n    }finally{\n\n        autoState.running=\n            false;\n    }\n}\n\n\n\n/* =========================================================\n   BIND ROOM\n========================================================= */\n\nfunction bindRoom(room){\n\n    const config=\n        getRoomConfig(room);\n\n\n    if(config.button){\n\n        config.button.addEventListener(\n            \"click\",\n            function(){\n\n                verifyStudent(room);\n            }\n        );\n    }\n\n\n    if(config.input){\n\n        config.input.addEventListener(\n            \"keydown\",\n            function(event){\n\n                if(\n                    event.key ===\n                    \"Enter\"\n                ){\n\n                    event.preventDefault();\n\n                    verifyStudent(room);\n                }\n\n            }\n        );\n\n\n        config.input.addEventListener(\n            \"input\",\n            function(){\n\n                const normalized=\n                    normalizeCode(\n                        config.input.value\n                    );\n\n\n                if(\n                    config.input.value !==\n                    normalized\n                ){\n\n                    config.input.value=\n                        normalized;\n                }\n\n\n                clearRoom(config);\n\n\n                /*\n                   Kh\u00f4ng clear OCDStudentSession \u1edf \u0111\u00e2y.\n                   Session d\u00f9ng chung to\u00e0n website.\n\n                   Ch\u1ec9 b\u1ecf context t\u1ea1m c\u1ee7a l\u1ea7n ki\u1ec3m tra\n                   Gi\u1ea3ng \u0111\u01b0\u1eddng hi\u1ec7n t\u1ea1i.\n                */\n\n                resetMinhHongState();\n\n            }\n        );\n    }\n}\n\n\n\n/* =========================================================\n   FILTER\n========================================================= */\n\nfunction bindFilters(){\n\n    const wrapper=\n        el(\"gdActivityFilters\");\n\n\n    if(!wrapper){\n\n        return;\n    }\n\n\n    wrapper.addEventListener(\n        \"click\",\n        function(event){\n\n            const button=\n                event.target.closest(\n                    \".gd-filter-button\"\n                );\n\n\n            if(!button){\n\n                return;\n            }\n\n\n            state.activityFilter=\n                button.getAttribute(\n                    \"data-filter\"\n                )\n                ||\n                \"all\";\n\n\n            state.visibleActivityCount=\n                CONFIG.activityPageSize;\n\n\n            wrapper\n            .querySelectorAll(\n                \".gd-filter-button\"\n            )\n            .forEach(\n                function(item){\n\n                    item.classList.toggle(\n                        \"active\",\n                        item === button\n                    );\n\n                }\n            );\n\n\n            renderActivities();\n\n        }\n    );\n}\n\n\n\n/* =========================================================\n   PUBLIC API\n========================================================= */\n\nwindow.OCDGiangDuong={\n\n    version:\n        \"1.9.0\",\n\n    verifyStudent:\n        verifyStudent,\n\n    getMinhHongContext:\n        function(){\n\n            return buildMinhHongContext();\n        },\n\n    syncMinhHongContext:\n        function(){\n\n            return syncMinhHongContext();\n        },\n\n    getState:\n        function(){\n\n            return{\n\n                directoryLoaded:\n                    Boolean(\n                        state.directory\n                    ),\n\n                legacyLoaded:\n                    Boolean(\n                        state.legacyDirectory\n                    ),\n\n                priorityLoaded:\n                    Boolean(\n                        state.priorityCodes\n                    ),\n\n                minhHong:\n                    buildMinhHongContext()\n\n            };\n        }\n\n};\n\n\n\n/* =========================================================\n   START\n========================================================= */\n\nfunction start(){\n\n    initUI();\n\n\n    bindRoom(\n        \"HOABINH\"\n    );\n\n\n    bindRoom(\n        \"HANHPHUC\"\n    );\n\n\n    bindFilters();\n\n\n\n    const loadMore=\n        el(\"gdLoadMore\");\n\n\n    if(loadMore){\n\n        loadMore.addEventListener(\n            \"click\",\n            function(){\n\n                state.visibleActivityCount +=\n                    CONFIG.activityPageSize;\n\n                state.lamMoShown=\n                    state.visibleActivityCount;\n\n\n                renderActivities();\n\n            }\n        );\n    }\n\n\n\n    const refresh=\n        el(\"gdRefreshActivity\");\n\n\n    if(refresh){\n\n        refresh.addEventListener(\n            \"click\",\n            loadActivities\n        );\n    }\n\n\n\n    /* =====================================================\n       PRELOAD HOCVIEN\n    ===================================================== */\n\n    setTimeout(\n        function(){\n\n            loadDirectory()\n            .catch(\n                function(error){\n\n                    console.warn(\n                        \"[Giang Duong v1.7.0 HocVien Preload]\",\n                        error\n                    );\n\n                }\n            );\n\n        },\n        100\n    );\n\n\n\n    /* =====================================================\n       PRELOAD XEPHANG\n    ===================================================== */\n\n    setTimeout(\n        function(){\n\n            loadLegacyDirectory()\n            .catch(\n                function(error){\n\n                    console.warn(\n                        \"[Giang Duong v1.7.0 XepHang Preload]\",\n                        error\n                    );\n\n                }\n            );\n\n        },\n        140\n    );\n\n\n\n    /* =====================================================\n       PRELOAD PRIORITY\n    ===================================================== */\n\n    setTimeout(\n        function(){\n\n            loadPriorityCodes()\n            .catch(\n                function(error){\n\n                    console.warn(\n                        \"[Giang Duong Priority Preload]\",\n                        error\n                    );\n\n                }\n            );\n\n        },\n        180\n    );\n\n\n\n    /* =====================================================\n       ROOM STATUS\n    ===================================================== */\n\n    updateRoomStatuses();\n\n\n    state.statusTimer=\n        setInterval(\n            updateRoomStatuses,\n            CONFIG.liveMeetStatus\n            .refreshInterval\n        );\n\n\n\n    /* =====================================================\n       ACTIVITY\n    ===================================================== */\n\n    setTimeout(\n        loadActivities,\n        300\n    );\n\n\n    state.activityTimer=\n        setInterval(\n            function(){\n\n                if(\n                    !document.hidden\n                ){\n\n                    loadActivities();\n                }\n\n            },\n            CONFIG.activityRefreshInterval\n        );\n\n\n    console.log(\n        \"[Giang Duong OCD] Lecture Hall v1.9.0 + Minh Hong auto + Lam mo gallery\"\n    );\n\n\n    /* =====================================================\n       v1.8.0 - T\u1ef0 NH\u1eacN DI\u1ec6N H\u1eccC VI\u00caN\n    ===================================================== */\n\n    [\n        \"ocdStudentSessionChanged\",\n        \"ocd:student-session-changed\",\n        \"ocdStudentVerified\",\n        \"ocdAuthChanged\"\n    ].forEach(\n        function(name){\n            window.addEventListener(\n                name,\n                function(){\n                    if(!sessionStudentCode()){\n                        autoState.code=\"\";\n                        return;\n                    }\n                    autoVerifySession();\n                }\n            );\n        }\n    );\n\n    [400,1200,2500,5000,9000].forEach(\n        function(ms){\n            setTimeout(\n                autoVerifySession,\n                ms\n            );\n        }\n    );\n}\n\n\n\n/* =========================================================\n   READY\n========================================================= */\n\nif(\n    document.readyState ===\n    \"loading\"\n){\n\n    document.addEventListener(\n        \"DOMContentLoaded\",\n        start,\n        {\n            once:true\n        }\n    );\n\n}else{\n\n    start();\n}\n\n\n})();\n</script>\n\n</div>\n");})();
